from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyLongCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.closes = []
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.block_entries_date = None
        self.spy_cleanup_ticket = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        current_date = self.Time.date()

        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if current_date >= expiry_date:
                self.block_entries_date = current_date
                self._submit_exit("expiration liquidation")
            else:
                previous_trading_day = self._previous_trading_day(expiry_date)

                if (
                    current_date == previous_trading_day
                    and self.Time.hour == 15
                    and self.Time.minute >= 45
                ):
                    self._submit_exit("pre-expiration time stop")

                self._check_profit_target(slice)

        spy_bar = slice.Bars[self.spy] if slice.Bars.ContainsKey(self.spy) else None
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time
        bar_end = bar.EndTime

        if bar_time.date() != self.Time.date():
            return

        if bar_time.time() < datetime.strptime("09:30", "%H:%M").time():
            return

        if bar_time.time() >= datetime.strptime("16:00", "%H:%M").time():
            return

        bucket_minute = (bar_time.minute // 5) * 5
        bucket_start = bar_time.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start
        elif bucket_start != self.bucket_start:
            self.bucket_start = bucket_start
            self.bucket_bars = []

        self.bucket_bars.append(bar)

        if bar_end.minute % 5 != 0 or bar_end.second != 0:
            return

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]
        actual_times = [b.Time for b in self.bucket_bars]

        complete = (
            len(self.bucket_bars) == 5
            and actual_times == expected_times
        )

        if complete:
            consolidated_close = self.bucket_bars[-1].Close
            consolidated_end = bar_end
            self._process_five_minute_close(
                consolidated_close,
                consolidated_end,
                slice
            )

        self.bucket_bars = []

    def _process_five_minute_close(self, close, bar_end, slice: Slice):
        if len(self.closes) >= 20:
            current_fast = sum(self.closes[-5:]) / 5.0
            current_slow = sum(self.closes[-20:]) / 20.0
        else:
            current_fast = None
            current_slow = None

        self.closes.append(float(close))
        if len(self.closes) > 20:
            self.closes.pop(0)

        if current_fast is None or current_slow is None:
            self.previous_fast = None
            self.previous_slow = None
            return

        new_fast = sum(self.closes[-5:]) / 5.0
        new_slow = sum(self.closes[-20:]) / 20.0

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and new_fast > new_slow
        )

        self.previous_fast = new_fast
        self.previous_slow = new_slow

        local_time = bar_end.time()
        eligible = (
            datetime.strptime("09:45", "%H:%M").time()
            <= local_time
            <= datetime.strptime("14:30", "%H:%M").time()
        )

        if not bullish_crossover or not eligible:
            return

        if (
            self.held_option is not None
            or self._entry_order_open()
            or self.block_entries_date == self.Time.date()
        ):
            return

        self._select_and_enter(slice)

    def _select_and_enter(self, slice: Slice):
        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no option chain")
            return

        chain = slice.OptionChains[self.option_symbol]
        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least 7 days out")
            return

        selected_expiry = expiries[0]
        calls = [
            contract for contract in chain
            if (
                contract.Expiry.date() == selected_expiry
                and contract.Right == OptionRight.Call
            )
        ]

        if not calls:
            self.Debug("Skipped entry: no call at selected expiration")
            return

        underlying_price = float(self.Securities[self.spy].Price)
        if underlying_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        selected = min(
            calls,
            key=lambda contract: (
                abs(float(contract.Strike) - underlying_price),
                float(contract.Strike),
                contract.Symbol.Value
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="bullish five-minute crossover entry"
        )
        self.Debug(
            "Entry submitted: {} {}",
            selected.Symbol.Value,
            selected_expiry
        )

    def _check_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        quote = None

        if slice.BidAskBars.ContainsKey(self.held_option):
            quote = slice.BidAskBars[self.held_option]
        elif slice.QuoteBars.ContainsKey(self.held_option):
            quote = slice.QuoteBars[self.held_option]

        if quote is None:
            return

        try:
            bid = float(quote.Bid.Close)
            ask = float(quote.Ask.Close)
        except Exception:
            return

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            try:
                self.exit_ticket.Cancel("replaced by " + reason)
            except Exception:
                pass

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {} ({})",
            self.held_option.Value,
            reason
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            order_event.OrderType == OrderType.OptionExercise
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Unexpected option exercise or assignment handled")
            self._handle_unexpected_spy_position()

        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    if order_event.FillQuantity > 0:
                        self.held_option = order_event.Symbol
                        self.entry_price = float(order_event.FillPrice)
                        self.entry_ticket = None
                        self.Debug(
                            "Entry filled: {} at {:.4f}",
                            order_event.Symbol.Value,
                            self.entry_price
                        )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.PartiallyFilled
                ) and order_event.Status != OrderStatus.PartiallyFilled:
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exit filled: {} at {:.4f}",
                        order_event.Symbol.Value,
                        float(order_event.FillPrice)
                    )
                    self.exit_ticket = None
                    self.held_option = None
                    self.entry_price = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if self.spy_cleanup_ticket is not None:
            if self.spy_cleanup_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ):
                return

        self.Debug("Unexpected SPY equity position liquidated")
        self.spy_cleanup_ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="unexpected exercise or assignment cleanup"
        )

