from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_count = 0
        self.bucket_last_minute = None
        self.bucket_close = None
        self.latest_spy_price = None

        self.held_symbol = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.blocked_dates = set()
        self.assignment_ticket = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        if self.held_symbol is not None:
            self._evaluate_held_position(slice)

        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is None:
            return

        self.latest_spy_price = float(spy_bar.Close)
        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        local_time = bar.Time
        current_date = local_time.date()
        current_minute = local_time.hour * 60 + local_time.minute

        if current_minute < 570 or current_minute >= 960:
            return

        bucket_minute = 570 + ((current_minute - 570) // 5) * 5
        bucket = datetime(
            current_date.year,
            current_date.month,
            current_date.day,
            bucket_minute // 60,
            bucket_minute % 60
        )

        if self.bucket_start is not None and bucket != self.bucket_start:
            self._finalize_bucket(slice)

        if self.bucket_start != bucket:
            self.bucket_start = bucket
            self.bucket_count = 1
            self.bucket_last_minute = local_time
            self.bucket_close = float(bar.Close)
            return

        expected_minute = self.bucket_last_minute + timedelta(minutes=1)

        if local_time != expected_minute:
            self.bucket_count = -1
        elif self.bucket_count > 0:
            self.bucket_count += 1

        self.bucket_last_minute = local_time
        self.bucket_close = float(bar.Close)

    def _finalize_bucket(self, slice: Slice):
        if self.bucket_start is None:
            return

        valid = (
            self.bucket_count == 5
            and self.bucket_last_minute == self.bucket_start + timedelta(minutes=4)
        )

        if valid:
            close = self.bucket_close
            self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
            self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

            self.fast.Update(self.bucket_start + timedelta(minutes=5), close)
            self.slow.Update(self.bucket_start + timedelta(minutes=5), close)

            bar_end = self.bucket_start + timedelta(minutes=5)
            eligible_time = (
                bar_end.hour * 60 + bar_end.minute >= 585
                and bar_end.hour * 60 + bar_end.minute <= 870
            )

            bullish_cross = (
                eligible_time
                and self.fast.IsReady
                and self.slow.IsReady
                and self.previous_fast is not None
                and self.previous_slow is not None
                and self.previous_fast <= self.previous_slow
                and self.fast.Current.Value > self.slow.Current.Value
            )

            if bullish_cross:
                self._try_enter(slice, bar_end.date())

        self.bucket_start = None
        self.bucket_count = 0
        self.bucket_last_minute = None
        self.bucket_close = None

    def _try_enter(self, slice: Slice, signal_date):
        if signal_date in self.blocked_dates:
            return

        if self.held_symbol is not None:
            return

        if self._order_is_open(self.entry_ticket):
            return

        chains = slice.OptionChains
        chain = chains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain")
            return

        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        contracts = [
            contract for contract in chain
            if contract.Expiry.date() >= minimum_expiry
            and contract.Right == OptionRight.Call
        ]

        if not contracts:
            self.Debug("Skipped entry: no eligible call contract")
            return

        selected_expiry = min(contract.Expiry.date() for contract in contracts)
        expiry_contracts = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
        ]

        if not expiry_contracts or self.latest_spy_price is None:
            self.Debug("Skipped entry: no contract at selected expiration")
            return

        selected = min(
            expiry_contracts,
            key=lambda contract: (
                abs(float(contract.Strike) - self.latest_spy_price),
                float(contract.Strike)
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="SPY call crossover entry"
        )
