        if self.assignment_ticket is None or not self._order_is_open(self.assignment_ticket):
            self.Debug("Unexpected exercise or assignment: liquidating SPY")
            self.assignment_ticket = self.MarketOrder(
                self.spy_symbol,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def _prior_trading_day(self, date_value):
        date_value -= timedelta(days=1)
        hours = self.Securities[self.spy_symbol].Exchange.Hours

        while date_value.weekday() >= 5 or not hours.IsDateOpen(
