                self._submit_exit("expiration")
            else:
                self._evaluate_exit(slice)

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            self._update_five_minute_bar(bar, slice)

    def _update_five_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time.replace(second=0, microsecond=0)
        session_start = datetime(bar_time.year, bar_time.month, bar_time.day, 9, 30)
        session_end = datetime(bar_time.year, bar_time.month, bar_time.day, 16, 0)

        if bar_time < session_start or bar_time >= session_end:
            return

        elapsed_minutes = int((bar_time - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(minutes=(elapsed_minutes // 5) * 5)

        if self.bucket_start != bucket_start:
            if self.bucket_start is not None and self.bucket_count == 5:
                self._process_five_minute_close(
                    self.bucket_start + timedelta(minutes=5),
                    self.bucket_close,
                    slice
                )

            self.bucket_start = bucket_start
            self.bucket_count = 0
            self.bucket_close = None

        expected_time = self.bucket_start + timedelta(minutes=self.bucket_count)
        if bar_time != expected_time:
            self.bucket_count = 0
            self.bucket_close = None
            return

        self.bucket_close = bar.Close
        self.bucket_count += 1

        if self.bucket_count == 5:
            self._process_five_minute_close(
                self.bucket_start + timedelta(minutes=5),
                self.bucket_close,
                slice
            )

    def _process_five_minute_close(self, end_time: datetime, close: float, slice: Slice):
        self.fast_values.append(close)
        if len(self.fast_values) > 20:
            self.fast_values.pop(0)

        if len(self.fast_values) < 20:
            return

        fast = sum(self.fast_values[-5:]) / 5.0
        slow = sum(self.fast_values[-20:]) / 20.0

        self.slow_values.append((fast, slow))

        if len(self.slow_values) < 2:
            return

        previous_fast, previous_slow = self.slow_values[-2]
        bullish_cross = previous_fast <= previous_slow and fast > slow

        end_clock = end_time.time()
        eligible_start = datetime(2000, 1, 1, 9, 45).time()
        eligible_end = datetime(2000, 1, 1, 14, 30).time()

        if (
            bullish_cross
            and eligible_start <= end_clock <= eligible_end
            and self.Time.date() != self.block_entries_date
            and self.held_option is None
            and not self._entry_order_open()
        ):
            self._enter_from_chain(slice)

    def _enter_from_chain(self, slice: Slice):
        if slice.OptionChains is None or len(slice.OptionChains) == 0:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiration = current_date + timedelta(days=7)

        contracts = []
        for chain in slice.OptionChains:
            for contract in chain:
                if contract.Right == OptionRight.Call:
                    contracts.append(contract)

        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        selected_expiration = expirations[0]
        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiration
        ]

        if not candidates:
            self.Debug("Skipped entry: no call at selected expiration.")
            return

        underlying_bar = slice.Bars.get(self.spy)
        underlying_price = (
            underlying_bar.Close
            if underlying_bar is not None
            else self.Securities[self.spy].Price
        )

        if underlying_price <= 0:
            self.Debug("Skipped entry: invalid underlying price.")
            return

        selected = min(
            candidates,
            key=lambda contract: (abs(contract.Strike - underlying_price), contract.Strike)
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish 5-minute crossover entry"
        )
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def _evaluate_exit(self, slice: Slice):
        if self.exit_ticket is not None and self._ticket_open(self.exit_ticket):
            return

        contract = None
        for chain in slice.OptionChains:
            for candidate in chain:
                if candidate.Symbol == self.held_option:
                    contract = candidate
                    break
            if contract is not None:
                break

        target_reached = False
        if (
            contract is not None
            and contract.BidPrice > 0
            and contract.AskPrice > 0
            and self.entry_price is not None
        ):
            midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
            target_reached = midpoint >= 1.5 * self.entry_price

        time_stop = (
            self._is_trading_day_before_expiration()
            and self.Time.hour == 15
            and self.Time.minute == 45
        )

        if target_reached:
            self._submit_exit("50% profit target")
        elif time_stop:
            self._submit_exit("expiration-eve time stop")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self._ticket_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by required liquidation")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -quantity,
                tag=reason
            )
            self.Debug("Exit submitted: " + reason)

    def _expiration_processing_started(self):
        if self.held_option is None:
            return False

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()
        return self.Time.date() >= expiry

    def _is_trading_day_before_expiration(self):
        if self.held_option is None:
            return False

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()
        current = self.Time.date()

        if current >= expiry:
            return False

        next_day = current + timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime(next_day.year, next_day.month, next_day.day)
        ):
            next_day += timedelta(days=1)

        return next_day >= expiry

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.block_entries_date = self.Time.date()
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.MarketOrder(self.spy, -quantity, tag="Unexpected exercise or assignment")

    def OnAssignmentOrder(self, assignment_event):
        self.block_entries_date = self.Time.date()
        self.Debug("Unexpected exercise or assignment received.")
        self._handle_unexpected_equity_position()

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: " + str(self.held_option)
                    + " at " + str(self.entry_price)
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug("Entry order did not fill.")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: " + str(order_event.Symbol))
            self.exit_ticket = None
            self.held_option = None
            self.entry_price = None

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self._ticket_open(self.entry_ticket)
        )

    @staticmethod
    def _ticket_open(ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

