from AlgorithmImports import *
from datetime import timedelta


class SpyBullishCrossoverCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._previous_fast = None
        self._previous_slow = None

        self._bucket_end = None
        self._bucket_count = 0
        self._bucket_close = None

        self._entry_ticket = None
        self._exit_ticket = None
        self._entry_price = None
        self._held_symbol = None
        self._held_expiry = None

        self._last_date = None
        self._no_entry_today = False
        self._equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self._last_date != current_date:
            self._last_date = current_date
            self._no_entry_today = False

        self._handle_unexpected_equity_position()
        self._process_expiration_and_time_stop()
        self._evaluate_profit_target(slice)

        bar = slice.Bars.get(self.spy_symbol)
        if bar is not None:
            self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        local_time = minute_bar.EndTime
        hour = local_time.hour
        minute = local_time.minute

        if hour < 9 or hour > 16 or (hour == 9 and minute <= 30):
            return

        if hour == 16 and minute > 0:
            return

        bucket_minute = ((minute + 4) // 5) * 5
        bucket_end = local_time.replace(
            minute=0,
            second=0,
            microsecond=0
        ) + timedelta(minutes=hour * 60 + bucket_minute)

        if self._bucket_end is None:
            self._bucket_end = bucket_end
        elif bucket_end != self._bucket_end:
            if self._bucket_count == 5:
                self._process_completed_five_minute_bar(
                    self._bucket_end,
                    self._bucket_close,
                    slice
                )

            self._bucket_end = bucket_end
            self._bucket_count = 0
            self._bucket_close = None

        self._bucket_count += 1
        self._bucket_close = minute_bar.Close

    def _process_completed_five_minute_bar(self, bar_end, close, slice: Slice):
        self._previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self._previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar_end, close)
        self.slow.Update(bar_end, close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if self._previous_fast is None or self._previous_slow is None:
            return

        local_end = bar_end.time()
        eligible_start = time(9, 45)
        eligible_end = time(14, 30)

        bullish_cross = (
            self._previous_fast <= self._previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if not bullish_cross:
            return

        if not (eligible_start <= local_end <= eligible_end):
            return

        if self._no_entry_today:
            return

        if self._has_option_holding() or self._order_is_open(self._entry_ticket):
            return

        self._enter_call(slice)

    def _enter_call(self, slice: Slice):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = list(chain.Contracts.Values)
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = expirations[0]
        calls = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
        ]

        if not calls:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        underlying_price = self.Securities[self.spy_symbol].Price
        if underlying_price <= 0:
            self.Debug("Skipped entry: invalid underlying price.")
            return

        selected = min(
            calls,
            key=lambda contract: (
                abs(contract.Strike - underlying_price),
                contract.Strike
            )
        )

        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol.Value}, "
            f"expiry {selected_expiry}."
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self._held_symbol is None or self._entry_price is None:
            return

        holding = self.Portfolio[self._held_symbol]
        if holding.Quantity <= 0:
            return

        quote = slice.QuoteBars.get(self._held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self._entry_price:
            self._submit_option_exit("profit target")

    def _process_expiration_and_time_stop(self):
        if self._held_symbol is None or self._held_expiry is None:
            return

        current_date = self.Time.date()

        if current_date >= self._held_expiry:
            self._no_entry_today = True
            self._submit_option_exit("expiration protection")
            return

        preceding_trading_day = self._preceding_trading_day(self._held_expiry)
        if (
            current_date == preceding_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_option_exit("time stop")

    def _submit_option_exit(self, reason: str):
        if self._held_symbol is None:
            return

        holding = self.Portfolio[self._held_symbol]
        quantity = holding.Quantity

        if quantity <= 0 or self._order_is_open(self._exit_ticket):
            return

        self.Transactions.CancelOpenOrders(self._held_symbol)
        self._exit_ticket = self.MarketOrder(self._held_symbol, -quantity)
        self.Debug(f"Exit submitted: {reason}.")

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy_symbol]

        if holding.Quantity == 0:
            return

        self._no_entry_today = True

        if self._equity_liquidation_ticket is None:
            self.Debug("Unexpected exercise or assignment: liquidating SPY.")
            self._equity_liquidation_ticket = self.Liquidate(self.spy_symbol)

    def _has_option_holding(self):
        return (
            self._held_symbol is not None
            and self.Portfolio[self._held_symbol].Quantity > 0
        )

    @staticmethod
    def _order_is_open(ticket):
        if ticket is None:
            return False

        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _preceding_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            DateTime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self._entry_ticket is not None
                and order_event.OrderId == self._entry_ticket.OrderId
            ):
                self._entry_price = order_event.FillPrice
                self._held_symbol = order_event.Symbol
                self._held_expiry = order_event.Symbol.ID.Date.date()
                self.Debug(
                    f"Entry filled: {order_event.Symbol.Value} "
                    f"at {order_event.FillPrice:.2f}."
                )

            elif (
                self._exit_ticket is not None
                and order_event.OrderId == self._exit_ticket.OrderId
            ):
                self.Debug(
                    f"Exit filled: {order_event.Symbol.Value} "
                    f"at {order_event.FillPrice:.2f}."
                )
                self._exit_ticket = None
                self._entry_price = None
                self._held_symbol = None
                self._held_expiry = None

            elif (
                self._equity_liquidation_ticket is not None
                and order_event.OrderId == self._equity_liquidation_ticket.OrderId
            ):
                self._equity_liquidation_ticket = None

            elif order_event.Symbol == self.spy_symbol:
                self._no_entry_today = True
                self.Debug("Unexpected SPY exercise or assignment handled.")

        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self._entry_ticket = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self._exit_ticket = None

        if (
            getattr(order_event, "IsAssignment", False)
            or getattr(order_event, "IsExercise", False)
        ):
            self._no_entry_today = True
            self.Debug("Unexpected exercise or assignment event received.")

