from datetime import timedelta


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_bars = {}

        self.contract_symbol = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.expiration_block_date = None
        self.assignment_ticket = None

    def OnData(self, data: Slice):
        self._handle_unexpected_equity_position()
        self._process_expiration()

        self._process_spy_minute_bar(data)
        self._evaluate_option_exit(data)

    def _process_spy_minute_bar(self, data: Slice):
        if not data.Bars.ContainsKey(self.spy.Symbol):
            return

        bar = data.Bars[self.spy.Symbol]
        end_time = bar.EndTime.replace(second=0, microsecond=0)
        local_time = end_time.time()

        # Regular-session minute bars end from 09:31 through 16:00.
        if local_time < time(9, 31) or local_time > time(16, 0):
            return

        calculated_end = end_time + timedelta(
            minutes=(5 - end_time.minute % 5) % 5
        )

        if self.bucket_end != calculated_end:
            self.bucket_end = calculated_end
            self.bucket_bars = {}

        self.bucket_bars[end_time] = bar

        if end_time != self.bucket_end:
            return

        expected_times = {
            self.bucket_end - timedelta(minutes=i)
            for i in range(5)
        }

        if set(self.bucket_bars.keys()) != expected_times:
            self.bucket_bars = {}
            return

        consolidated_close = self.bucket_bars[self.bucket_end].Close
        self.bucket_bars = {}

        self._process_consolidated_bar(
            self.bucket_end,
            consolidated_close,
            data
        )

    def _process_consolidated_bar(self, end_time, close, data: Slice):
        current_fast = self.fast.Current.Value if self.fast.IsReady else None
        current_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(end_time, close)
        self.slow.Update(end_time, close)

        if current_fast is None or current_slow is None:
            self.previous_fast = (
                self.fast.Current.Value if self.fast.IsReady else None
            )
            self.previous_slow = (
                self.slow.Current.Value if self.slow.IsReady else None
            )
            return

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self.previous_fast = self.fast.Current.Value
        self.previous_slow = self.slow.Current.Value

        bar_time = end_time.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if bullish_crossover and eligible_time:
            self._try_enter(data)

    def _try_enter(self, data: Slice):
        today = self.Time.date()

        if self.expiration_block_date == today:
            return

        if self._entry_or_option_position_exists():
            return

        chains = list(data.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain")
            return

        chain = None
        for candidate in chains:
            if candidate.Symbol.Underlying == self.spy.Symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped entry: no SPY option chain")
            return

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= today + timedelta(days=7)
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 days away")
            return

        selected_expiration = expirations[0]

        calls = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
        ]

        if not calls:
            self.Debug("Skipped entry: no call at selected expiration")
            return

        underlying_price = self.Securities[self.spy.Symbol].Price
        if underlying_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        selected = min(
            calls,
            key=lambda contract: (
                abs(contract.Strike - underlying_price),
                contract.Strike
            )
        )

        self.contract_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(self.contract_symbol, 1)

        self.Debug(
            "Entry submitted: {} exp {} strike {:.2f}".format(
                self.contract_symbol,
                selected_expiration,
                selected.Strike
            )
        )

    def _evaluate_option_exit(self, data: Slice):
        if self.contract_symbol is None:
            return

        holding = self.Portfolio[self.contract_symbol]
        if holding.Quantity <= 0 or self.entry_price is None:
            return

        # The time stop is independent of quote availability.
        if (
            self.Time.date() == self._previous_trading_day(
                self.contract_symbol.ID.Date.date()
            )
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("time stop")
            return

        if self._exit_order_open():
            return

        contract = self._find_contract_in_slice(data, self.contract_symbol)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50% profit target")

    def _process_expiration(self):
        if self.contract_symbol is None:
            return

        expiration_date = self.contract_symbol.ID.Date.date()
        if self.Time.date() < expiration_date:
            return

        if self.expiration_block_date != self.Time.date():
            self.expiration_block_date = self.Time.date()
            self.Debug("Expiration processing started")

        holding = self.Portfolio[self.contract_symbol]
        if holding.Quantity > 0:
            self._submit_exit("expiration protection")

    def _submit_exit(self, reason):
        if self.contract_symbol is None:
            return

        holding = self.Portfolio[self.contract_symbol]
        if holding.Quantity <= 0:
            return

        if self._exit_order_open():
            return

        if self.entry_ticket is not None and self._order_open(self.entry_ticket):
            return

        if self.exit_ticket is not None and self._order_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.contract_symbol,
            -holding.Quantity
        )
        self.Debug("Exit submitted: {}".format(reason))

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy.Symbol]
        if holding.Quantity == 0:
            return

        if self.assignment_ticket is None or not self._order_open(
            self.assignment_ticket
        ):
            self.Debug("Unexpected exercise or assignment: liquidating SPY")
            self.assignment_ticket = self.MarketOrder(
                self.spy.Symbol,
                -holding.Quantity
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if (
                order_event.Status == OrderStatus.Filled
                and order_event.FillQuantity > 0
            ):
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.contract_symbol,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: {}".format(self.contract_symbol))
            self.exit_ticket = None
            self.contract_symbol = None
            self.entry_price = None

        message = (order_event.Message or "").lower()
        if "assign" in message or "exercis" in message:
            self.Debug("Unexpected exercise or assignment event")

    def _find_contract_in_slice(self, data: Slice, symbol):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _entry_or_option_position_exists(self):
        if self.entry_ticket is not None and self._order_open(self.entry_ticket):
            return True

        if self.contract_symbol is None:
            return False

        return self.Portfolio[self.contract_symbol].Quantity > 0

    def _exit_order_open(self):
        return (
            self.exit_ticket is not None
            and self._order_open(self.exit_ticket)
        )

    def _order_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted
        )

    def _previous_trading_day(self, date_value):
        date_value -= timedelta(days=1)
        while not self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(
            date_value
        ):
            date_value -= timedelta(days=1)
        return date_value


