from datetime import timedelta, time


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(
            DataNormalizationMode.Raw
        )

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)

        self._bucket_date = None
        self._bucket_end = None
        self._bucket_bars = []
        self._previous_fast = None
        self._previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.contract_expiry = None

        self.no_entry_today = None
        self.equity_cleanup_ticket = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self._handle_unexpected_spy_position(today)
        self._handle_expiration_processing(today)

        spy_bar = None
        if slice.Bars.ContainsKey(self.spy):
            spy_bar = slice.Bars[self.spy]

        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

        self._process_held_option_exit(slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_end = bar.EndTime
        bar_date = bar_end.date()

        if bar_date != self._bucket_date:
            self._bucket_date = bar_date
            self._bucket_end = None
            self._bucket_bars = []

        if bar_end.time() <= time(9, 30) or bar_end.time() > time(16, 0):
            return

        boundary_minute = ((bar_end.minute + 4) // 5) * 5
        bucket_end = bar_end.replace(
            minute=0, second=0, microsecond=0
        ) + timedelta(minutes=boundary_minute)

        if self._bucket_end is None:
            self._bucket_end = bucket_end
            self._bucket_bars = []
        elif bucket_end != self._bucket_end:
            self._bucket_end = bucket_end
            self._bucket_bars = []

        self._bucket_bars.append(bar)

        if bar_end.minute % 5 != 0:
            return

        completed_bars = self._bucket_bars
        completed_end = self._bucket_end
