        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(lambda universe: universe
                         .IncludeWeeklys()
                         .Strikes(-100, 100)
                         .Expiration(0, 365))
        self.option = option

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.entry_expiry = None

        self.exit_ticket = None
        self.no_entries_today = False
        self.last_session_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.last_session_date != current_date:
            self.last_session_date = current_date
            self.no_entries_today = False

        self._handle_expiration_processing()
        self._evaluate_profit_target(slice)
        self._evaluate_time_stop()

        if not slice.Bars.ContainsKey(self.spy):
            return

        bar = slice.Bars[self.spy]
        local_time = bar.Time.time()

        if local_time < time(9, 31) or local_time > time(16, 0):
            return

        bucket_end = self._five_minute_bucket_end(bar.Time)

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_bars = []

        self.bucket_bars.append(bar)

        if len(self.bucket_bars) != 5:
            return

        timestamps = [x.Time for x in self.bucket_bars]
        expected = [
            self.bucket_bars[0].Time + timedelta(minutes=i)
            for i in range(5)
        ]

        if timestamps != expected:
            self.bucket_bars = []
            return

        close = self.bucket_bars[-1].Close
        completed_end = bucket_end

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(IndicatorDataPoint(completed_end, close))
        self.slow.Update(IndicatorDataPoint(completed_end, close))

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if self.no_entries_today:
            return

        if self.entry_ticket is not None and self._is_order_open(self.entry_ticket):
            return

        if self.entry_symbol is not None:
            holding = self.Portfolio[self.entry_symbol]
            if holding.Invested:
                return

        if self.entry_expiry is not None and current_date >= self.entry_expiry:
            return

        if completed_end.time() < time(9, 45) or completed_end.time() > time(14, 30):
            return

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish_cross:
            self._try_enter(slice)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_expiry = self.Securities[
                    order_event.Symbol
                ].Symbol.ID.Date.date()

                self.Debug(
                    "Entry filled: {} call at {:.2f}, expiry {}".format(
                        order_event.Symbol,
                        self.entry_price,
                        self.entry_expiry
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(order_event.Symbol))
                self.exit_ticket = None
                self.entry_symbol = None
                self.entry_price = None
                self.entry_expiry = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_ticket = None

    def OnAssignmentOrder(self, assignment_order):
        self.Debug("Unexpected option exercise or assignment detected.")

        equity_holding = self.Portfolio[self.spy]
        if equity_holding.Invested:
            self.MarketOrder(
                self.spy,
                -equity_holding.Quantity,
                tag="Liquidate unexpected assignment"
            )

        self.no_entries_today = True

    def _try_enter(self, slice: Slice):
        if not slice.OptionChains.ContainsKey(self.option.Symbol):
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = slice.OptionChains[self.option.Symbol]
        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days out.")
            return

        selected_expiry = expirations[0]

        calls = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
        ]

        if not calls:
            self.Debug("Skipped entry: no call at selected expiration.")
            return

        underlying_price = self.Securities[self.spy].Price
        if underlying_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        selected = min(
            calls,
            key=lambda contract: (
                abs(contract.Strike - underlying_price),
                contract.Strike
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover call entry"
        )

        self.Debug(
            "Submitted entry: {} call, expiry {}, strike {:.2f}".format(
                selected.Symbol,
                selected_expiry,
                selected.Strike
            )
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.entry_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested:
            return

        if self.exit_ticket is not None and self._is_order_open(self.exit_ticket):
            return

        bid_quote = slice.BidQuotes.get(self.entry_symbol)
        ask_quote = slice.AskQuotes.get(self.entry_symbol)

        if bid_quote is None or ask_quote is None:
            return

        bid = bid_quote.Close
        ask = ask_quote.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _evaluate_time_stop(self):
        if self.entry_symbol is None or self.entry_expiry is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested:
