from datetime import timedelta, time


class SpyBullishCrossoverCall(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._bucket_date = None
        self._bucket_end = None
        self._bucket_minutes = {}
        self._previous_fast = None
        self._previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self._entry_blocked_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        # An exercise or assignment must never leave an SPY equity position open.
        equity_quantity = self.Portfolio[self.spy].Quantity
        if equity_quantity != 0:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating immediately."
            )
            self.MarketOrder(self.spy, -equity_quantity)

        # Expiration safeguard.
        if self.held_option is not None:
            expiration_date = self.held_option.ID.Date.date()
            if current_date >= expiration_date:
                self._entry_blocked_date = current_date
                self._submit_exit("expiration safeguard")

        # Evaluate exits on every minute Slice.
        self._evaluate_exits()

        if self.spy not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy]
        self._update_five_minute_bar(minute_bar, slice)

    def _update_five_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        local_end = self.Time.replace(second=0, microsecond=0)
        local_date = local_end.date()

        if not (time(9, 31) <= local_end.time() <= time(16, 0)):
            return

        minutes_since_open = (
            local_end.hour * 60 + local_end.minute
        ) - (9 * 60 + 30)

        bucket_number = (minutes_since_open - 1) // 5
        bucket_end = self.Time.replace(
            hour=9,
            minute=35,
            second=0,
            microsecond=0
        ) + timedelta(minutes=5 * bucket_number)

        if (
            self._bucket_end is not None
            and (local_date != self._bucket_date or bucket_end != self._bucket_end)
        ):
            self._finalize_bucket(slice)

        if self._bucket_end != bucket_end or self._bucket_date != local_date:
            self._bucket_date = local_date
            self._bucket_end = bucket_end
            self._bucket_minutes = {}

        self._bucket_minutes[local_end] = minute_bar

        if local_end == bucket_end:
            self._finalize_bucket(slice)

    def _finalize_bucket(self, slice: Slice):
        if self._bucket_end is None or not self._bucket_minutes:
            return

        expected_times = [
            self._bucket_end - timedelta(minutes=i)
            for i in range(5, 0, -1)
        ]

        if not all(t in self._bucket_minutes for t in expected_times):
            self._bucket_minutes = {}
            return

        bars = [self._bucket_minutes[t] for t in expected_times]

        consolidated = TradeBar(
            self._bucket_end - timedelta(minutes=5),
            self.spy,
            timedelta(minutes=5),
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars)
        )

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(consolidated.EndTime, consolidated.Close)
        self.slow.Update(consolidated.EndTime, consolidated.Close)

        if self.fast.IsReady and self.slow.IsReady:
            bullish_cross = (
                previous_fast is not None
                and previous_slow is not None
                and previous_fast <= previous_slow
                and self.fast.Current.Value > self.slow.Current.Value
            )

            end_time = consolidated.EndTime.time()
            eligible_time = time(9, 45) <= end_time <= time(14, 30)

            if bullish_cross and eligible_time:
                self._try_enter(slice, consolidated.Close)

        self._bucket_minutes = {}

    def _try_enter(self, slice: Slice, underlying_price: float):
        current_date = self.Time.date()

        if self._entry_blocked_date == current_date:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None:
            if self.entry_ticket.Status not in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Filled
            ):
                return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiration = current_date + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days out.")
            return

        selected_expiration = expirations[0]

        calls = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
        ]

        if not calls:
            self.Debug("Skipped entry: no call contract at selected expiration.")
            return

        selected = min(
            calls,
            key=lambda contract: (
                abs(float(contract.Strike) - float(underlying_price)),
                float(contract.Strike)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} expiring {} strike {:.2f}".format(
                selected.Symbol,
                selected_expiration,
                float(selected.Strike)
            )
        )

    def _evaluate_exits(self):
        if self.held_option is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        expiration_date = self.held_option.ID.Date.date()
        previous_trading_day = (
            self.Securities[self.spy]
            .Exchange
            .Hours
            .GetPreviousTradingDay(expiration_date)
            .date()
        )

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")
            return

        contract_data = self.CurrentSlice.OptionChains
        chain = contract_data.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (c for c in chain if c.Symbol == self.held_option),
            None
        )

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            if self.exit_ticket.Status not in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Filled
            ):
                return

        self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
        self.Debug("Exit submitted: {}".format(reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_option,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(order_event.Symbol))
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        if (
            getattr(order_event, "IsAssignment", False)
            or getattr(order_event, "IsExercise", False)
        ):
            self._entry_blocked_date = self.Time.date()
            equity_quantity = self.Portfolio[self.spy].Quantity
            self.Debug("Unexpected exercise or assignment processed.")
            if equity_quantity != 0:
                self.MarketOrder(self.spy, -equity_quantity)

