        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = expiration_date - timedelta(days=1)

        for _ in range(14):
            candidate_dt = datetime.combine(candidate, time(0, 0))
            if exchange_hours.IsDateOpen(candidate_dt):
                return candidate
            candidate -= timedelta(days=1)

        return expiration_date - timedelta(days=1)

