    def _is_order_open(ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted,
        )

    def OnOrderEvent(self, order_event):
        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                f"Unexpected option exercise or assignment event: "
                f"{order_event.Symbol}"
            )
            self._no_entry_date = self.Time.date()

        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if (
                order_event.Status == OrderStatus.Filled
                and order_event.FillQuantity > 0
            ):
                self._held_option = order_event.Symbol
                self._entry_price = order_event.FillPrice
                self._expiration_date = (
                    self.Securities[self._held_option].Symbol.ID.Date.date()
                )
                self.Debug(
                    f"Entry filled: {self._held_option} "
                    f"price={self._entry_price}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.Debug(
                    f"Entry order did not fill: {order_event.Status}"
                )
                self._entry_ticket = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                f"Exit filled: {order_event.Symbol} "
                f"price={order_event.FillPrice}"
            )
            self._held_option = None
            self._entry_price = None
            self._expiration_date = None
            self._exit_ticket = None
            self._entry_ticket = None

