        self.fast_period = 5
        self.slow_period = 20
        self.fast_values = []
        self.slow_values = []
        self.previous_fast = None
        self.previous_slow = None

        self.current_date = None
        self.current_bucket = None
        self.bucket_closes = {}
        self.bucket_count = 0

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_block_date = None
        self.assignment_liquidation_submitted = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.current_date != current_date:
            self.current_date = current_date
            self.current_bucket = None
            self.bucket_closes = {}
            self.bucket_count = 0
            self.assignment_liquidation_submitted = False

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing()
        self._evaluate_option_exit(slice)

        completed_bar = self._update_five_minute_bar(slice)

        if completed_bar is not None:
            self._evaluate_entry(completed_bar, slice)

    def _update_five_minute_bar(self, slice: Slice):
        if self.spy not in slice.Bars:
            return None

        minute_bar = slice.Bars[self.spy]
        local_time = minute_bar.Time

        if local_time.date() != self.current_date:
            return None

        session_start = time(9, 30)
        session_end = time(16, 0)

        if local_time.time() < session_start or local_time.time() >= session_end:
            return None

        minutes_from_open = (
            local_time.hour * 60 + local_time.minute
            - (session_start.hour * 60 + session_start.minute)
