from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option = option
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.bucket_start = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_fill_price = None
        self.expiry_date = None
        self.time_stop_date = None
        self.expiration_block_date = None

    def OnData(self, data: Slice):
        current_date = self.Time.date()

        if self.Portfolio[self.spy].Invested:
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.Liquidate(self.spy)

        if self.held_symbol is not None and self.expiry_date is not None:
            if current_date >= self.expiry_date:
                self._liquidate_option("expiration processing")

        spy_bar = None
        if data.Bars.ContainsKey(self.spy):
            spy_bar = data.Bars[self.spy]

        if spy_bar is not None:
            self._process_minute_bar(spy_bar, data)

        if self.held_symbol is not None and self.entry_fill_price is not None:
            self._evaluate_exit(data)

    def _process_minute_bar(self, bar: TradeBar, data: Slice):
        end_time = self.Time
        minute = end_time.replace(second=0, microsecond=0)

        if minute.time() < time(9, 31) or minute.time() > time(16, 0):
            return

        bucket = minute - timedelta(
            minutes=(minute.hour * 60 + minute.minute - 30) % 5
        )

        if self.bucket_start is None:
            self.bucket_start = bucket

        if bucket != self.bucket_start:
            self._finalize_bucket(data)
            self.bucket_start = bucket
            self.bucket_bars = []

        self.bucket_bars.append((minute, bar))

        if minute == self.bucket_start + timedelta(minutes=4):
            self._finalize_bucket(data)
            self.bucket_start = None
            self.bucket_bars = []

    def _finalize_bucket(self, data: Slice):
        if self.bucket_start is None:
            return

        expected = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]
        actual = [timestamp for timestamp, _ in self.bucket_bars]

        if actual != expected:
            self.bucket_start = None
            self.bucket_bars = []
            return

        close = self.bucket_bars[-1][1].Close

        previous_fast = None
        previous_slow = None
        if len(self.closes) >= self.slow_period:
            previous_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            previous_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        self.closes.append(close)
        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bar_end = self.bucket_start + timedelta(minutes=5)
        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if bullish_cross and eligible_time:
            self._try_enter(data)

    def _try_enter(self, data: Slice):
        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
            return

        if self.expiration_block_date == self.Time.date():
            return

        chain = None
        try:
            chain = data.OptionChains[self.option.Symbol]
        except Exception:
            chain = None

        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        eligible = []

        for contract in chain:
            expiry = contract.Expiry.date()
            if expiry >= current_date + timedelta(days=7):
                eligible.append(contract)

        if not eligible:
            self.Debug("Skipped entry: no eligible expiration.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in eligible)

        calls = [
            contract for contract in eligible
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
        ]

        if not calls:
            self.Debug("Skipped entry: no eligible call contract.")
            return

        underlying_price = self.Securities[self.spy].Price
        if underlying_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        calls.sort(key=lambda contract: (abs(contract.Strike - underlying_price),
                                         contract.Strike))
        selected = calls[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Call entry submitted: {selected.Symbol}, "
            f"expiry {selected_expiry}"
        )

    def _evaluate_exit(self, data: Slice):
        if self.held_symbol is None:
            return

        position = self.Portfolio[self.held_symbol]
        if not position.Invested:
            return

        current_date = self.Time.date()
        current_time = self.Time.time()

        if (
            self.time_stop_date is not None
            and current_date == self.time_stop_date
            and current_time >= time(15, 45)
        ):
            self._liquidate_option("time stop")
            return

        if not data.QuoteBars.ContainsKey(self.held_symbol):
            return

        quote = data.QuoteBars[self.held_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_fill_price:
            self._liquidate_option("profit target")

    def _liquidate_option(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by liquidation order")

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug(f"Option exit submitted: {reason}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.expiry_date = order_event.Symbol.ID.Date.date()
                self.time_stop_date = self._previous_trading_day(self.expiry_date)
                self.Debug(
                    f"Call entry filled: {self.held_symbol}, "
                    f"price {self.entry_fill_price}"
                )

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Call exit filled: {order_event.Symbol}")
                self.held_symbol = None
                self.entry_fill_price = None
                self.expiry_date = None
                self.time_stop_date = None
                self.exit_ticket = None

        try:
            if order_event.IsAssignment:
                self.Debug("Unexpected option exercise or assignment detected.")
                if self.Portfolio[self.spy].Invested:
                    self.Liquidate(self.spy)
                self.expiration_block_date = self.Time.date()
        except Exception:
            pass

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug("Unexpected option assignment handling.")
        if self.Portfolio[self.spy].Invested:
            self.Liquidate(self.spy)
        self.expiration_block_date = self.Time.date()

    def _previous_trading_day(self, date_value):
        day = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while True:
            try:
                is_open = exchange_hours.IsDateOpen(
                    datetime(day.year, day.month, day.day)
                )
            except Exception:
                is_open = day.weekday() < 5

            if is_open:
                return day

            day -= timedelta(days=1)

    @staticmethod
    def _order_is_open(ticket):
        if ticket is None:
