from datetime import timedelta, time


class SpyLongCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .Strikes(-100, 100)
                .Expiration(timedelta(0), timedelta(days=365))
        )
        self.option_symbol = self.spy_option.Symbol

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_day_blocked = None
        self.assignment_liquidation_ticket = None

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy,
            self.five_minute_consolidator
        )

        self.pending_signal_bar = None

    def OnFiveMinuteBar(self, sender, bar):
        bar_start = bar.EndTime - timedelta(minutes=5)
        session_start = time(9, 30)
        session_end = time(16, 0)

        if bar_start.time() < session_start or bar.EndTime.time() > session_end:
            return

        previous_fast = None
        previous_slow = None

        if self.fast_window.IsReady:
            previous_fast = sum(self.fast_window) / self.fast_window.Count
        if self.slow_window.IsReady:
            previous_slow = sum(self.slow_window) / self.slow_window.Count

        self.fast_window.Add(float(bar.Close))
        self.slow_window.Add(float(bar.Close))

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        current_fast = sum(self.fast_window) / self.fast_window.Count
        current_slow = sum(self.slow_window) / self.slow_window.Count

        if previous_fast is None or previous_slow is None:
            return

        eligible_start = time(9, 45)
        eligible_end = time(14, 30)

        if (
            eligible_start <= bar.EndTime.time() <= eligible_end
            and previous_fast <= previous_slow
            and current_fast > current_slow
        ):
            self.pending_signal_bar = bar

    def OnData(self, slice):
        current_date = self.Time.date()

        self.HandleUnexpectedEquityPosition()

        if self.held_option is not None:
            self.EvaluateExit(slice)

        if (
            self.held_option is not None
            and self.held_option.ID.Date.date() <= current_date
        ):
            self.expiration_day_blocked = current_date
            self.SubmitExit("expiration processing")

        if (
            self.pending_signal_bar is not None
            and self.pending_signal_bar.EndTime <= self.Time
        ):
            signal_bar = self.pending_signal_bar
            self.pending_signal_bar = None

            if self.expiration_day_blocked == current_date:
                return

            if self.held_option is not None or self.IsEntryOrderOpen():
                return

            self.TryEnter(slice, signal_bar)

    def TryEnter(self, slice, signal_bar):
        chain = None

        for candidate_chain in slice.OptionChains:
            if candidate_chain.Symbol == self.option_symbol:
                chain = candidate_chain
                break

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        minimum_expiration = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiration
        })

        if len(expirations) == 0:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiration = expirations[0]
        underlying_price = float(self.Securities[self.spy].Price)

        if underlying_price <= 0:
            self.Debug("Skipped entry: unavailable SPY price.")
            return

        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiration
            and contract.Strike > 0
        ]

        if len(calls) == 0:
            self.Debug("Skipped entry: no call contract at selected expiration.")
            return

        selected_contract = min(
            calls,
            key=lambda contract: abs(float(contract.Strike) - underlying_price)
        )

        self.entry_ticket = self.MarketOrder(
            selected_contract.Symbol,
            1,
            tag="Bullish five-minute MA crossover"
        )

    def EvaluateExit(self, slice):
        if self.held_option is None:
            return

        symbol = self.held_option.Symbol
        holding = self.Portfolio[symbol]

        if holding.Quantity <= 0:
            return

        expiration_date = self.held_option.Expiry.date()
        current_date = self.Time.date()

        if self.IsImmediatelyPrecedingTradingDay(current_date, expiration_date):
            if self.Time.time() >= time(15, 45):
                self.SubmitExit("pre-expiration time stop")
                return

        contract = None
        for chain in slice.OptionChains:
            if chain.Symbol != self.option_symbol:
                continue
            for candidate in chain:
                if candidate.Symbol == symbol:
                    contract = candidate
                    break
            break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("50 percent profit target")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        symbol = self.held_option.Symbol
        quantity = self.Portfolio[symbol].Quantity

        if quantity <= 0:
            return

        if self.IsExitOrderOpen():
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(
            symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted for {0}: {1}".format(symbol.Value, reason)
        )

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_option = self.Securities[order_event.Symbol]
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Call entry filled: {0}, price {1:.4f}".format(
                        order_event.Symbol.Value,
                        self.entry_price
                    )
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    "Call exit filled: {0}, price {1:.4f}".format(
                        order_event.Symbol.Value,
                        float(order_event.FillPrice)
                    )
                )
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None

        assignment = getattr(order_event, "IsAssignment", False)
        if callable(assignment):
            assignment = assignment()

        if assignment:
            self.Debug(
                "Unexpected option exercise or assignment: {0}".format(
                    order_event.Symbol.Value
                )
            )
            self.expiration_day_blocked = self.Time.date()

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            return

        if self.assignment_liquidation_ticket is None:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating immediately."
            )
            self.expiration_day_blocked = self.Time.date()
            self.assignment_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def IsEntryOrderOpen(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def IsExitOrderOpen(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def IsImmediatelyPrecedingTradingDay(self, current_date, expiration_date):
        candidate = current_date + timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate += timedelta(days=1)

        return candidate == expiration_date

