        self.bucket_end = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.entry_fill_quantity = 0
        self.entry_fill_value = 0

        self.no_entry_date = None
        self.equity_liquidation_pending = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()

        if self.held_symbol is not None:
            self._manage_open_option(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        completed_bar = self._update_five_minute_bar(spy_bar)
        if completed_bar is None:
            return

        self._evaluate_entry(slice, completed_bar)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Symbol == self.spy and order_event.FillQuantity != 0:
            self.Debug(
                "Unexpected SPY exercise/assignment activity detected; "
                "liquidating the entire SPY position."
            )
            self.no_entry_date = self.Time.date()
            self._liquidate_spy_position()

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
                self.entry_fill_quantity += order_event.FillQuantity
                self.entry_fill_value += (
                    order_event.FillQuantity * order_event.FillPrice
                )

                if self.entry_fill_quantity > 0:
                    self.entry_price = (
                        self.entry_fill_value / self.entry_fill_quantity
                    )

                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.Debug(
                        "Entered {0} call, quantity {1}, filled price {2:.2f}".format(
                            self.held_symbol.Value,
                            self.entry_fill_quantity,
                            self.entry_price,
                        )
                    )
                    self.entry_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected,
            ):
                self.entry_ticket = None
                self.entry_fill_quantity = 0
                self.entry_fill_value = 0
                self.entry_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exited {0} at filled price {1:.2f}".format(
                        order_event.Symbol.Value,
                        order_event.FillPrice,
                    )
                )
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
                self.entry_fill_quantity = 0
                self.entry_fill_value = 0

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected,
            ):
                self.exit_ticket = None

    def _update_five_minute_bar(self, minute_bar):
        end_time = minute_bar.EndTime
        local_end = end_time.time()

        if local_end < time(9, 30) or local_end > time(16, 0):
            return None

        bucket_minute = (end_time.minute // 5) * 5
        bucket_end = end_time.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0,
        ) + timedelta(minutes=5)

        bucket_key = (end_time.date(), bucket_end)

