            self.bucket_date = end_time.date()
            self.bucket_end = bucket_key
            self.bucket_bars = []

        if self.bucket_bars:
            previous_end = self.bucket_bars[-1].EndTime
            if end_time != previous_end + timedelta(minutes=1):
                self.bucket_bars = []

        self.bucket_bars.append(minute_bar)

        if end_time != bucket_end:
            return None

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(5, 0, -1)
        ]
        actual_times = [bar.EndTime for bar in self.bucket_bars]

        if actual_times != expected_times:
            self.bucket_bars = []
            return None

        bars = self.bucket_bars
        self.bucket_bars = []

        return {
            "EndTime": bucket_end,
            "Open": bars[0].Open,
            "High": max(bar.High for bar in bars),
            "Low": min(bar.Low for bar in bars),
            "Close": bars[-1].Close,
            "Volume": sum(bar.Volume for bar in bars),
        }

    def _evaluate_entry(self, slice, five_minute_bar):
        bar_end = five_minute_bar["EndTime"]
        bar_time = bar_end.time()

        self.closes.append(five_minute_bar["Close"])
        if len(self.closes) > self.slow_period + 1:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period + 1:
            return

        previous_closes = self.closes[:-1]
        current_closes = self.closes

        previous_fast = sum(previous_closes[-self.fast_period:]) / self.fast_period
        previous_slow = sum(previous_closes[-self.slow_period:]) / self.slow_period
        current_fast = sum(current_closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(current_closes[-self.slow_period:]) / self.slow_period

        crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not crossover:
            return

        if not (time(9, 45) <= bar_time <= time(14, 30)):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None or self._entry_order_open():
            return

        self._select_and_enter_call(slice, five_minute_bar["Close"])

    def _select_and_enter_call(self, slice, underlying_price):
        if not slice.OptionChains:
            self.Debug("Skipped call selection: current Slice has no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        chains = list(slice.OptionChains.Values)
        contracts = [
            contract
            for chain in chains
            for contract in chain
            if contract.Right == OptionRight.Call
        ]

        expirations = sorted({
            contract.Expiration.date()
            for contract in contracts
            if contract.Expiration.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped call selection: no expiration is at least 7 days away.")
            return

        selected_expiry = expirations[0]
        eligible_calls = [
            contract
            for contract in contracts
            if contract.Expiration.date() == selected_expiry
            and contract.Strike > 0
        ]

        if not eligible_calls:
            self.Debug(
                "Skipped call selection: no call contract at selected expiration."
            )
            return

        selected = min(
            eligible_calls,
            key=lambda contract: (
                abs(contract.Strike - underlying_price),
                contract.Strike,
            ),
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Submitted market entry for {0}, expiration {1}, strike {2:.2f}".format(
                selected.Symbol.Value,
                selected.Expiration.date(),
                selected.Strike,
            )
        )

    def _manage_open_option(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        position = self.Portfolio[self.held_symbol]
        if not position.Invested:
            return

        contract_expiry = self.held_symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= contract_expiry:
            self.no_entry_date = current_date
            self._submit_exit("expiration processing")
            return

        if (
            self._is_immediately_preceding_trading_day(
                current_date,
                contract_expiry,
            )
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")
            return

        if self.exit_ticket is not None:
            return

        quote = slice.QuoteBars.get(self.held_symbol)
        if quote is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.CancelPending,
            ):
                self.exit_ticket.Cancel("Replacing open exit order")
            self.exit_ticket = None

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                -quantity,
                tag=reason,
            )
            self.Debug(
                "Submitted market exit for {0}: {1}".format(
                    self.held_symbol.Value,
                    reason,
                )
            )

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
        )

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating immediately."
            )
            self.no_entry_date = self.Time.date()
            self._liquidate_spy_position()

    def _liquidate_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0 and not self.equity_liquidation_pending:
            self.equity_liquidation_pending = True
            self.MarketOrder(self.spy, -quantity, tag="Unexpected exercise/assignment")
        elif quantity == 0:
            self.equity_liquidation_pending = False

    def _is_immediately_preceding_trading_day(self, current_date, expiry_date):
        candidate = current_date + timedelta(days=1)

        while candidate < expiry_date:
            candidate_datetime = datetime(
                candidate.year,
                candidate.month,
                candidate.day,
            )
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                candidate_datetime
            ):
                return False
            candidate += timedelta(days=1)

        return candidate == expiry_date and self.Securities[
            self.spy
        ].Exchange.Hours.IsDateOpen(
            datetime(expiry_date.year, expiry_date.month, expiry_date.day)
        )

