    def _is_immediately_preceding_trading_day(self, current_date, expiry_date):
        candidate = current_date + timedelta(days=1)

        while candidate < expiry_date:
            candidate_datetime = datetime(
                candidate.year,
                candidate.month,
                candidate.day,
            )
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                candidate_datetime
            ):
                return False
            candidate += timedelta(days=1)

