            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_index = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.cleanup_ticket = None

        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._process_expiration_and_equity(current_date)

        completed_bar = None
        if slice.Bars.ContainsKey(self.spy):
            completed_bar = self._update_five_minute_bar(slice.Bars[self.spy])

        if completed_bar is not None:
            bar_end, close = completed_bar
            signal = self._update_averages(close)

            if (
                signal
                and time(9, 45) <= bar_end.time() <= time(14, 30)
                and self.no_entry_date != current_date
            ):
                self._try_enter(slice, current_date)

        self._evaluate_held_option(slice, current_date)

    def _update_five_minute_bar(self, minute_bar):
        bar_time = minute_bar.Time
        bar_date = bar_time.date()
        session_start = time(9, 30)
        session_end = time(16, 0)

        if not (session_start <= bar_time.time() < session_end):
            return None

        if self.bucket_date != bar_date:
            self.bucket_date = bar_date
            self.bucket_index = None
            self.bucket_bars = {}

        minutes_from_open = (
            bar_time.hour * 60 + bar_time.minute
            - (session_start.hour * 60 + session_start.minute)
        )
        bucket_index = minutes_from_open // 5

        completed = None
        if self.bucket_index is not None and bucket_index != self.bucket_index:
            completed = self._complete_bucket()

        if self.bucket_index != bucket_index:
            self.bucket_index = bucket_index
            self.bucket_bars = {}

        self.bucket_bars[bar_time] = minute_bar

        return completed

    def _complete_bucket(self):
        if len(self.bucket_bars) != 5:
            self.bucket_bars = {}
            return None

        ordered_times = sorted(self.bucket_bars.keys())
        first_time = ordered_times[0]
        expected_times = [
            first_time + timedelta(minutes=i)
            for i in range(5)
        ]

        if ordered_times != expected_times:
            self.bucket_bars = {}
            return None

        last_bar = self.bucket_bars[ordered_times[-1]]
        completed = (last_bar.EndTime, last_bar.Close)
        self.bucket_bars = {}
        return completed

    def _update_averages(self, close):
        prior_fast = None
        prior_slow = None

        if len(self.closes) >= self.slow_period:
            values = list(self.closes)
            prior_fast = sum(values[-self.fast_period:]) / self.fast_period
            prior_slow = sum(values) / self.slow_period

        self.closes.append(close)

        if len(self.closes) < self.slow_period:
            self.previous_fast = None
            self.previous_slow = None
            return False

        values = list(self.closes)
        current_fast = sum(values[-self.fast_period:]) / self.fast_period
        current_slow = sum(values) / self.slow_period

        bullish_cross = (
            prior_fast is not None
            and prior_slow is not None
            and prior_fast <= prior_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow
        return bullish_cross

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False
        return self.entry_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.CancelPending
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False
        return self.exit_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.CancelPending
        )

    def _try_enter(self, slice: Slice, current_date):
        if self.held_symbol is not None or self._entry_order_open():
            return

        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain")
            return

        minimum_expiry = current_date + timedelta(days=7)
        chains = list(slice.OptionChains.Values)

        contracts = []
        for chain in chains:
            for contract in chain:
                expiry_date = contract.Symbol.ID.Date.date()
                if (
                    expiry_date >= minimum_expiry
                    and contract.Symbol.ID.OptionRight == OptionRight.Call
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying expiration or call")
            return

        selected_expiry = min(
            contract.Symbol.ID.Date.date()
            for contract in contracts
        )

        expiry_contracts = [
            contract for contract in contracts
            if contract.Symbol.ID.Date.date() == selected_expiry
        ]

        if not expiry_contracts or not slice.Bars.ContainsKey(self.spy):
            self.Debug("Skipped entry: no qualifying strike")
            return

        underlying_price = slice.Bars[self.spy].Close
        selected = min(
            expiry_contracts,
            key=lambda contract: (
                abs(contract.Strike - underlying_price),
                contract.Strike
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol.Value}, "
            f"expiry {selected_expiry}"
        )

    def _evaluate_held_option(self, slice: Slice, current_date):
        if self.held_symbol is None or self.entry_price is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if current_date >= expiry_date:
            self.no_entry_date = current_date
            self._submit_exit("expiration protection")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)
        if (
            current_date == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("time stop")
            return

        if self._exit_order_open():
            return

        contract = self._find_contract(slice, self.held_symbol)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._cancel_open_exit()
            self._submit_exit("50% profit target")

    def _find_contract(self, slice: Slice, symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._exit_order_open():
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = holding.Quantity

        if quantity == 0:
            return

        self._cancel_open_exit()
        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason}")

    def _cancel_open_exit(self):
        if self._exit_order_open():
            self.exit_ticket.Cancel("Canceled for replacement exit")

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _process_expiration_and_equity(self, current_date):
        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()
            if current_date >= expiry_date:
                self.no_entry_date = current_date
                self._submit_exit("expiration protection")

        spy_holding = self.Portfolio[self.spy]
        if spy_holding.Invested:
            if (
                self.cleanup_ticket is None
                or self.cleanup_ticket.Status in (
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                )
            ):
                self.Debug("Unexpected exercise or assignment: liquidating SPY")
                self.cleanup_ticket = self.MarketOrder(
                    self.spy,
                    -spy_holding.Quantity,
                    tag="Unexpected exercise or assignment cleanup"
                )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.held_symbol = order_event.Symbol
            self.entry_price = order_event.FillPrice
            self.Debug(
                f"Entry filled: {self.held_symbol.Value} "
                f"at {self.entry_price}"
            )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Exit filled: {order_event.Symbol.Value}")
            if not self.Portfolio[order_event.Symbol].Invested:
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None

        message = (order_event.Message or "").lower()
        if "assignment" in message or "exercise" in message:
            self.Debug("Unexpected exercise or assignment event received")
            spy_holding = self.Portfolio[self.spy]
            if spy_holding.Invested:
                self.cleanup_ticket = self.MarketOrder(
                    self.spy,
                    -spy_holding.Quantity,
                    tag="Exercise or assignment cleanup"
                )

