from datetime import datetime, date, time, timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(lambda universe: universe
                         .IncludeWeeklys()
                         .Strikes(-200, 200)
                         .Expiration(0, 730))
        self.spy_option = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.bucket_end = None
        self.bucket_closes = []
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_block_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()
        self._process_expiration(current_date)

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            self._evaluate_exit(slice, current_date)

        if self.held_option is None and not self._is_open(self.entry_ticket):
            self._process_minute_bar(slice)

    def _process_minute_bar(self, slice: Slice):
        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        end = bar.EndTime
        session_start = time(9, 30)
        session_end = time(16, 0)

        if end.time() <= session_start or end.time() > session_end:
            return

        minutes_from_open = int((end - end.replace(
            hour=9, minute=30, second=0, microsecond=0
        )).total_seconds() / 60)

        if minutes_from_open < 1 or minutes_from_open > 390:
            return

        interval_start_minute = ((minutes_from_open - 1) // 5) * 5 + 1
        expected_end = end.replace(
            hour=9, minute=30, second=0, microsecond=0
        ) + timedelta(minutes=interval_start_minute + 4)

        if minutes_from_open % 5 == 1:
            self.bucket_end = expected_end
            self.bucket_closes = [bar.Close]
            return

        if self.bucket_end != expected_end:
            self.bucket_end = None
            self.bucket_closes = []
            return

        self.bucket_closes.append(bar.Close)

        if len(self.bucket_closes) != 5:
            return

        close = self.bucket_closes[-1]
        completed_end = self.bucket_end
        self.bucket_end = None
        self.bucket_closes = []

        if completed_end.time() < time(9, 45) or completed_end.time() > time(14, 30):
            self._update_averages(close)
            return

        self._update_averages(close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if self.previous_fast is None or self.previous_slow is None:
            return

        bullish_cross = (
            self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish_cross:
            self._select_and_enter(slice)

    def _update_averages(self, close):
        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(self.Time, close)
        self.slow.Update(self.Time, close)

    def _select_and_enter(self, slice: Slice):
        if self.expiration_block_date == self.Time.date():
            return

