from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self._bucket_date = None
        self._bucket_end = None
        self._bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_fill_price = None
        self.expiration_block_date = None
        self.equity_liquidation_pending = False

    def OnData(self, data: Slice):
        today = self.Time.date()

        # No strategy replacement or new entry on an expiration-processing day.
        if self.held_option is not None:
            expiration_date = self.held_option.ID.Date.date()

            if today >= expiration_date:
                self.expiration_block_date = today
                self._submit_exit("expiration processing")
            elif self._is_pre_expiration_trading_day(today, expiration_date):
                if self.Time.hour == 15 and self.Time.minute == 45:
                    self._submit_exit("pre-expiration time stop")
            else:
                self._evaluate_profit_target(data)

        # Handle any unexpected SPY equity position caused by exercise or assignment.
        spy_quantity = self.Portfolio[self.spy.Symbol].Quantity
        if spy_quantity != 0:
            if not self.equity_liquidation_pending:
                self.Debug(
                    "Unexpected exercise/assignment created SPY position; liquidating."
                )
                self.Liquidate(self.spy.Symbol)
                self.equity_liquidation_pending = True
        else:
            self.equity_liquidation_pending = False

        bar = data.Bars.get(self.spy.Symbol)
        if bar is not None:
            self._accumulate_minute_bar(bar, data)

    def _accumulate_minute_bar(self, bar: TradeBar, data: Slice):
        end_time = bar.EndTime
        local_date = end_time.date()
        local_time = end_time.time()

        if local_time < time(9, 31) or local_time > time(16, 0):
            return

        minute = end_time.hour * 60 + end_time.minute
        bucket_end_minutes = ((minute + 4) // 5) * 5
        bucket_end = datetime(
            local_date.year,
            local_date.month,
            local_date.day
        ) + timedelta(minutes=bucket_end_minutes)

        if self._bucket_end != bucket_end:
            if self._bucket_bars:
                self._finalize_bucket(data)

            self._bucket_date = local_date
            self._bucket_end = bucket_end
            self._bucket_bars = []

        self._bucket_bars.append(bar)

    def _finalize_bucket(self, data: Slice):
        if self._bucket_end is None:
            return

        expected_start = self._bucket_end - timedelta(minutes=4)
        valid = (
            len(self._bucket_bars) == 5
            and self._bucket_bars[0].EndTime == expected_start
            and all(
                self._bucket_bars[i].EndTime
                == expected_start + timedelta(minutes=i)
                for i in range(5)
            )
        )

        if not valid:
            self._bucket_bars = []
            return

        close = self._bucket_bars[-1].Close
        end_time = self._bucket_end
        self._bucket_bars = []

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        end_clock = end_time.time()
        eligible_time = time(9, 45) <= end_clock <= time(14, 30)

        if bullish_cross and eligible_time:
            self._attempt_entry(data, close, end_time.date())

    def _attempt_entry(self, data: Slice, underlying_price: float, algorithm_date):
        if self.expiration_block_date == algorithm_date:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self._ticket_closed(self.entry_ticket):
            return

        chain = data.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped call selection: no option chain in current Slice.")
            return

        minimum_expiry = algorithm_date + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped call selection: no expiration at least 7 days away.")
            return

        selected_expiry = expirations[0]
        calls = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
        ]

        if not calls:
            self.Debug("Skipped call selection: no call at selected expiration.")
            return

        selected = min(
            calls,
            key=lambda contract: abs(contract.Strike - underlying_price)
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} call, expiration {}, strike {}.".format(
                selected.Symbol.Value,
                selected_expiry,
                selected.Strike
            )
        )

    def _evaluate_profit_target(self, data: Slice):
        if self.held_option is None or self.entry_fill_price is None:
            return

        quote = data.QuoteBars.get(self.held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_fill_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and not self._ticket_closed(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order: " + reason)

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
        self.Debug(
            "Exit submitted: {} ({})".format(self.held_option.Value, reason)
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.PartiallyFilled
                ):
                    if order_event.FillQuantity > 0:
                        self.held_option = order_event.Symbol
                        if self.entry_fill_price is None:
                            self.entry_fill_price = order_event.FillPrice
                            self.Debug(
                                "Entry filled: {} at {:.4f}.".format(
                                    order_event.Symbol.Value,
                                    order_event.FillPrice
                                )
                            )

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Exit filled: {}.".format(order_event.Symbol.Value))
                    if self.Portfolio[order_event.Symbol].Quantity == 0:
                        self.held_option = None
                        self.entry_fill_price = None
                        self.exit_ticket = None

    def _is_pre_expiration_trading_day(self, current_date, expiration_date):
        if current_date >= expiration_date:
            return False

        candidate = current_date + timedelta(days=1)
        while candidate < expiration_date:
            candidate_dt = datetime.combine(candidate, time.min)
            if self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(
                candidate_dt
            ):
                return False
            candidate += timedelta(days=1)

        return True

    def _ticket_closed(self, ticket):
        return ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

