        ask = held_contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self.SubmitOptionLiquidation("50% profit target")

    def SubmitOptionLiquidation(self, tag):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.Transactions.CancelOpenOrders(self.held_option)
        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=tag,
        )

    def IsTradingDayImmediatelyBefore(self, expiration_date, current_date):
        if current_date >= expiration_date:
            return False

        previous_trading_day = expiration_date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime.combine(previous_trading_day, time.min)
        ):
            previous_trading_day -= timedelta(days=1)

        return current_date == previous_trading_day

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_expiration = self.Securities[
                    self.held_option
                ].Symbol.ID.Date

                self.Debug(
                    f"Entered {self.held_option} at filled price "
                    f"{self.entry_price:.4f}."
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    f"Exited {order_event.Symbol} at filled price "
                    f"{order_event.FillPrice:.4f}."
                )
                self.held_option = None
                self.entry_price = None
                self.entry_expiration = None
                self.exit_ticket = None

        message = (order_event.Message or "").lower()
        if "exercise" in message or "assignment" in message:
            self.block_entry_date = self.Time.date()
            self.Debug(
                f"Unexpected option exercise/assignment event: "
                f"{order_event.Message}"
            )

