        if self._held_contract is not None:
            held_quantity = self.Portfolio[self._held_contract].Quantity

            if held_quantity <= 0 and self._entry_ticket is None and self._exit_ticket is None:
                self.Debug("Unexpected option position disappearance; clearing state.")
                self._clear_position_state()

            elif held_quantity > 0:
                expiration_date = self._held_contract.ID.Date.date()

                if current_date >= expiration_date:
                    self._blocked_entry_date = current_date
                    self._submit_option_exit("expiration processing")
