        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        local_start = bar.Time
        local_time = local_start.time()

        if local_time < time(9, 30) or local_time >= time(16, 0):
            return

        minutes_from_open = (local_start.hour * 60 + local_start.minute) - (9 * 60 + 30)
        bucket_start = datetime(
            local_start.year,
            local_start.month,
            local_start.day,
            9,
            30
        ) + timedelta(minutes=(minutes_from_open // 5) * 5)

        if self._bucket_start is not None and bucket_start != self._bucket_start:
            self._emit_completed_bucket(slice)

        if self._bucket_start != bucket_start:
            self._bucket_start = bucket_start
            self._minute_bars = {}

        minute_key = local_start.replace(second=0, microsecond=0)
        self._minute_bars[minute_key] = bar

