        if self._bucket_start is None:
            return

        expected = [
            self._bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(key not in self._minute_bars for key in expected):
            self._minute_bars = {}
            return

        bars = [self._minute_bars[key] for key in expected]

        consolidated = TradeBar()
        consolidated.Symbol = self.spy
        consolidated.Time = self._bucket_start
        consolidated.EndTime = self._bucket_start + timedelta(minutes=5)
        consolidated.Open = bars[0].Open
        consolidated.High = max(bar.High for bar in bars)
        consolidated.Low = min(bar.Low for bar in bars)
        consolidated.Close = bars[-1].Close
        consolidated.Volume = sum(bar.Volume for bar in bars)

        previous_fast = self.fast.Current.Value
        previous_slow = self.slow.Current.Value
        averages_ready = self.fast.IsReady and self.slow.IsReady

        self.fast.Update(consolidated.EndTime, consolidated.Close)
        self.slow.Update(consolidated.EndTime, consolidated.Close)

        if averages_ready:
            bullish_cross = (
                previous_fast <= previous_slow
                and self.fast.Current.Value > self.slow.Current.Value
            )

            bar_end_time = consolidated.EndTime.time()
            eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

            if bullish_cross and eligible_time:
                self._evaluate_entry(slice, consolidated.Close)

        self._minute_bars = {}

    def _evaluate_entry(self, slice: Slice, underlying_price: float):
        current_date = self.Time.date()

        if self._blocked_entry_date == current_date:
            return

        if self._held_contract is not None:
            return

        if self._entry_ticket is not None and not self._entry_ticket.Status.IsClosed():
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiration = current_date + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        selected_expiration = expirations[0]
        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
        ]

        if not candidates:
            self.Debug("Skipped entry: no call contract at selected expiration.")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                abs(contract.Strike - underlying_price),
                contract.Strike
            )
        )

        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiration {selected_expiration}, strike {selected.Strike:.2f}"
        )

    def _check_profit_target(self, slice: Slice):
        if self._held_contract is None or self._entry_price is None:
            return

        if self._exit_ticket is not None and not self._exit_ticket.Status.IsClosed():
            return

        quote = slice.QuoteBars.get(self._held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._submit_option_exit("50% profit target")

    def _submit_option_exit(self, reason: str):
        if self._held_contract is None:
            return

        quantity = self.Portfolio[self._held_contract].Quantity
        if quantity <= 0:
            return

        self._cancel_open_exit()
        self._exit_ticket = self.MarketOrder(
            self._held_contract,
            -quantity
        )
        self.Debug(f"Exit submitted: {self._held_contract} ({reason})")

    def _cancel_open_exit(self):
        if self._exit_ticket is not None and not self._exit_ticket.Status.IsClosed():
            self._exit_ticket.Cancel("Superseded by liquidation")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self._entry_ticket is not None
                and order_event.OrderId == self._entry_ticket.OrderId
            ):
                self._held_contract = order_event.Symbol
                self._entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {order_event.Symbol}, "
                    f"price {order_event.FillPrice:.4f}"
                )

            elif (
                self._exit_ticket is not None
                and order_event.OrderId == self._exit_ticket.OrderId
            ):
                self.Debug(
                    f"Exit filled: {order_event.Symbol}, "
                    f"price {order_event.FillPrice:.4f}"
                )
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self._clear_position_state()

        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            )
        ):
            self.Debug(f"Entry order did not fill: {order_event.Status}")
            self._entry_ticket = None

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0 and not self._assignment_liquidation_submitted:
            self.Debug(
                f"Unexpected exercise or assignment created SPY position: "
                f"{quantity}; liquidating immediately."
            )
            self.MarketOrder(self.spy, -quantity)
            self._assignment_liquidation_submitted = True
            self._blocked_entry_date = self.Time.date()

        elif quantity == 0:
            self._assignment_liquidation_submitted = False

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _clear_position_state(self):
        self._entry_ticket = None
        self._held_contract = None
        self._entry_price = None
        self._exit_ticket = None

