from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_values = []
        self.bucket_invalid = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None

        self.expiration_blocked_dates = set()
        self.unexpected_equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        now = self.Time
        current_date = now.date()

        self._handle_unexpected_equity_position()
        self._process_expiration()
        self._evaluate_open_position(slice)

        if self._entry_order_is_open() or self._has_option_holding():
            return

        if current_date in self.expiration_blocked_dates:
            return

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        minute_start = bar.Time.replace(second=0, microsecond=0)
        local_time = minute_start.time()

        if local_time < time(9, 30) or local_time >= time(16, 0):
            return

        if self.bucket_start is None:
            if minute_start.minute % 5 != 0:
                return
            self._start_bucket(minute_start, bar)
            return

        expected_end = self.bucket_start + timedelta(minutes=5)

        if minute_start < self.bucket_start:
            return

        if minute_start >= expected_end:
            self._complete_bucket(expected_end, slice)

            self.bucket_start = None
            self.bucket_values = []
            self.bucket_invalid = False

            if minute_start.minute % 5 != 0:
                return

            self._start_bucket(minute_start, bar)
            return

        expected_minute = self.bucket_start + timedelta(minutes=len(self.bucket_values))

        if minute_start != expected_minute:
            self.bucket_invalid = True

        self.bucket_values.append(bar)

    def _start_bucket(self, minute_start: datetime, bar: TradeBar):
        self.bucket_start = minute_start
        self.bucket_values = [bar]
        self.bucket_invalid = False

    def _complete_bucket(self, bar_end: datetime, slice: Slice):
        if self.bucket_start is None:
            return

        if self.bucket_invalid or len(self.bucket_values) != 5:
            return

        close = self.bucket_values[-1].Close
        self.closes.append(float(close))

        if len(self.closes) < 20:
            return

        fast = sum(list(self.closes)[-5:]) / 5.0
        slow = sum(self.closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_time = bar_end.time()
        eligible = time(9, 45) <= bar_time <= time(14, 30)

        if bullish_cross and eligible:
            self._attempt_entry(slice)

    def _attempt_entry(self, slice: Slice):
        if self._entry_order_is_open() or self._has_option_holding():
            return

        chains = []
        for chain in slice.OptionChains.Values:
            chains.append(chain)

        if not chains:
            self.Debug("Skipped entry: no option chain")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = []
        for chain in chains:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry and contract.Strike > 0:
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no eligible call contracts")
            return

        selected_expiry = min(contract.Expiry.date() for contract in contracts)
        expiry_contracts = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
        ]

        underlying_price = self.Securities[self.spy].Price
        if underlying_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        selected = min(
            expiry_contracts,
            key=lambda contract: (
                abs(contract.Strike - underlying_price),
                contract.Strike
            )
        )

        self.held_option = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiry={selected.Expiry.date()} strike={selected.Strike}"
        )

    def _evaluate_open_position(self, slice: Slice):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0:
            return

        if self._exit_order_is_open():
            return

        expiration_date = self.held_option.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiration_date:
            self.expiration_blocked_dates.add(current_date)
            self._submit_option_exit("Expiration processing")
            return

        if (
            self.entry_price is not None and
            self._is_previous_trading_day(current_date, expiration_date) and
            self.Time.time() >= time(15, 45)
        ):
            self._submit_option_exit("Expiration-eve time stop")
            return

        quote = self._get_current_option_quote(slice, self.held_option)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_option_exit("50 percent profit target")

    def _get_current_option_quote(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return float(contract.BidPrice), float(contract.AskPrice)

        if symbol in slice.BidAskBars:
            quote = slice.BidAskBars[symbol]
            return float(quote.Bid.Close), float(quote.Ask.Close)

        return None

    def _submit_option_exit(self, reason: str):
        if self.held_option is None or self._exit_order_is_open():
            return

        if self.entry_ticket is not None and self._entry_order_is_open():
            return

        holding = self.Portfolio[self.held_option]
        quantity = holding.Quantity

        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing prior exit order")
            self.exit_ticket = None

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason}")

    def _process_expiration(self):
        if self.held_option is None:
            return

        expiration_date = self.held_option.ID.Date.date()
        if self.Time.date() >= expiration_date:
            self.expiration_blocked_dates.add(self.Time.date())
            self._submit_option_exit("Expiration processing")

    def _is_previous_trading_day(self, current_date, expiration_date):
        candidate = expiration_date - timedelta(days=1)

        while candidate >= current_date:
            try:
                is_open = self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                    candidate
                )
            except Exception:
                is_open = candidate.weekday() < 5

            if is_open:
                return current_date == candidate

            candidate -= timedelta(days=1)

        return False

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            return

        if (
            self.unexpected_equity_liquidation_ticket is not None and
            self.unexpected_equity_liquidation_ticket.Status
            not in [OrderStatus.Canceled, OrderStatus.Invalid, OrderStatus.Filled]
        ):
            return

        self.unexpected_equity_liquidation_ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )
        self.Debug("Unexpected SPY exercise or assignment handled")

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option assignment handled")
        self._handle_unexpected_equity_position()

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {self.held_option} "
                    f"price={self.entry_price}"
                )
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.Debug("Entry order canceled or invalid")
                self.entry_ticket = None
                self.held_option = None
                self.entry_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self.held_option}")
                self.exit_ticket = None
                self.entry_ticket = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.exit_ticket = None

        order = self.Transactions.GetOrder(order_event.OrderId)
        order_type = str(order.Type).lower()

        if "exercise" in order_type or "assignment" in order_type:
            self.Debug("Unexpected exercise or assignment order detected")
            self._handle_unexpected_equity_position()

    def _has_option_holding(self):
        return (
            self.held_option is not None and
            self.Portfolio[self.held_option].Quantity > 0
        )

    def _entry_order_is_open(self):
        return (
            self.entry_ticket is not None and
            self.entry_ticket.Status not in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]
        )

    def _exit_order_is_open(self):
        return (
            self.exit_ticket is not None and
            self.exit_ticket.Status not in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]
        )

