            sum(self.fast_window[i] for i in range(1, 6)) / 5.0
        )
        previous_slow = (
            sum(self.slow_window[i] for i in range(1, 21)) / 20.0
        )

        bullish_crossover = (
            previous_fast <= previous_slow and fast > slow
        )

        eligible_time = (
            five_minute_end.time() >= TimeSpan.FromHours(9.75).ToTimeSpan()
            if False else
            five_minute_end.hour > 9 or
            (five_minute_end.hour == 9 and five_minute_end.minute >= 45)
        )
        eligible_time = eligible_time and (
            five_minute_end.hour < 14 or
            (five_minute_end.hour == 14 and five_minute_end.minute <= 30)
        )

        if bullish_crossover and eligible_time:
            self._try_enter(slice, today)

