        bucket_start = current_minute.replace(
            minute=(current_minute.minute // 5) * 5
        )

        if self._five_minute_bucket is None:
            self._five_minute_bucket = bucket_start
        elif bucket_start != self._five_minute_bucket:
            result = self._finalize_five_minute_bar()
            self._five_minute_bucket = bucket_start
            self._minute_bars = {}
            self._minute_bars[current_minute] = minute_bar
            return result

        self._minute_bars[current_minute] = minute_bar
        return None, None

