        if self._five_minute_bucket is None:
            return None, None

        expected = [
            self._five_minute_bucket + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(t not in self._minute_bars for t in expected):
            return None, None

        bars = [self._minute_bars[t] for t in expected]
        close = bars[-1].Close
        end_time = self._five_minute_bucket + timedelta(minutes=5)
        return close, end_time

