        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            self.entry_ticket.Cancel("Exit condition triggered")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {0} ({1})".format(
                self.held_option.Value,
                reason
            )
        )

    def _handle_expiration_processing(self, today):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        if today >= expiry_date:
            self.no_entry_date = today
            self._submit_exit("Expiration processing")

    def _handle_unexpected_equity_position(self, today):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity == 0:
            return

        self.no_entry_date = today
        self.Debug(
            "Unexpected exercise or assignment: liquidating SPY equity."
        )
        self.MarketOrder(
            self.spy_symbol,
            -quantity,
            tag="Unexpected exercise or assignment handling"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        order = self.Transactions.GetOrderById(order_event.OrderId)

        if order.Symbol == self.spy_symbol and (
            order.Type == OrderType.OptionExercise or
            "exercise" in order_event.Message.lower() or
            "assignment" in order_event.Message.lower()
        ):
            self.no_entry_date = self.Time.date()
            self.Debug("Unexpected exercise or assignment event received.")
            quantity = self.Portfolio[self.spy_symbol].Quantity
            if quantity != 0:
                self.MarketOrder(
                    self.spy_symbol,
                    -quantity,
                    tag="Unexpected exercise or assignment handling"
                )
            return

        if self.entry_ticket is not None and (
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order.Symbol
                self.entry_price = order_event.FillPrice
                expiry = order.Symbol.ID.Date.date()
                self.time_stop_date = self._previous_trading_day(expiry)
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        order.Symbol.Value,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.Debug("Entry order canceled or invalid.")

        if self.exit_ticket is not None and (
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {0}".format(order.Symbol.Value))
                self.held_option = None
                self.entry_price = None
                self.time_stop_date = None
                self.exit_ticket = None

    def _previous_trading_day(self, date_value):
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours
        candidate = date_value - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _ticket_is_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

