from datetime import timedelta, time, datetime


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.fast_sum = 0.0
        self.slow_sum = 0.0
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_bars = []
        self.bucket_date = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.no_entry_today = False
        self.equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.bucket_date != current_date:
            self.bucket_date = current_date
            self.bucket_end = None
            self.bucket_bars = []
            self.no_entry_today = False

        self._handle_unexpected_equity_position()
        self._process_option_expiration()

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

        self._process_option_exit(slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        local_time = end_time.time()

        if local_time <= time(9, 30) or local_time > time(16, 0):
            return

        session_start = datetime(
            end_time.year,
            end_time.month,
            end_time.day,
            9,
            30
        )
        elapsed_minutes = int((end_time - session_start).total_seconds() // 60)
        bucket_number = (elapsed_minutes + 4) // 5
        bucket_end = session_start + timedelta(minutes=bucket_number * 5)

        if self.bucket_end is None:
            self.bucket_end = bucket_end
            self.bucket_bars = []
        elif bucket_end != self.bucket_end:
            self._finish_bucket(slice)
            self.bucket_end = bucket_end
            self.bucket_bars = []

        self.bucket_bars.append(bar)

    def _finish_bucket(self, slice: Slice):
        if self.bucket_end is None:
            return

        bars = self.bucket_bars
        if len(bars) != 5:
            return

        expected_end = self.bucket_end - timedelta(minutes=4)
        for bar in bars:
            if bar.EndTime != expected_end:
                return
            expected_end += timedelta(minutes=1)

        close = bars[-1].Close

        if len(self.fast_values) == self.fast_values.maxlen:
            self.fast_sum -= self.fast_values.popleft()
        self.fast_values.append(close)
        self.fast_sum += close

        if len(self.slow_values) == self.slow_values.maxlen:
            self.slow_sum -= self.slow_values.popleft()
        self.slow_values.append(close)
        self.slow_sum += close

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        fast = self.fast_sum / 5.0
        slow = self.slow_sum / 20.0

        bullish_crossover = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        bar_end_time = self.bucket_end.time()
        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

        self.previous_fast = fast
        self.previous_slow = slow

        if (
            bullish_crossover and
            eligible_time and
            not self.no_entry_today and
            self.held_option is None and
            not self._is_order_open(self.entry_ticket)
        ):
            self._try_enter(slice, close)

    def _try_enter(self, slice: Slice, underlying_price: float):
        chain = None
        for candidate in slice.OptionChains.Values:
            if candidate.Symbol == self.option_symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped call selection: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= current_date + timedelta(days=7)
        })

        if not expirations:
            self.Debug("Skipped call selection: no expiration at least seven days out.")
            return

        selected_expiry = expirations[0]
        calls = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike > 0
        ]

        if not calls:
            self.Debug("Skipped call selection: no eligible call at selected expiration.")
            return

        selected = min(
            calls,
            key=lambda contract: (abs(contract.Strike - underlying_price), contract.Strike)
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Call entry submitted: {selected.Symbol.Value}, "
            f"expiry {selected.Expiry.date()}, strike {selected.Strike}."
        )

    def _process_option_exit(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self._is_order_open(self.exit_ticket):
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0:
            return

        if self._is_pre_expiration_time():
            self._submit_exit("time stop")
            return

        bid = None
        ask = None

        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(self.held_option)
            if contract is not None:
                bid = contract.BidPrice
                ask = contract.AskPrice
                break

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50% profit target")

    def _is_pre_expiration_time(self):
        if self.held_option is None:
            return False

        expiry_date = self.held_option.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            return False

        prior_trading_day = expiry_date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(prior_trading_day):
            prior_trading_day -= timedelta(days=1)

        return (
            current_date == prior_trading_day and
            self.Time.time() == time(15, 45)
        )

    def _process_option_expiration(self):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.no_entry_today = True
            if self.Portfolio[self.held_option].Quantity != 0:
                self._submit_exit("expiration protection")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        if self._is_order_open(self.exit_ticket):
            return

        self.Transactions.CancelOpenOrders(self.held_option)
        self.exit_ticket = self.Liquidate(self.held_option)
        self.Debug(f"Option exit submitted: {reason}.")

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Quantity == 0:
            return

        if not self._is_order_open(self.equity_liquidation_ticket):
            self.Debug("Unexpected SPY exercise or assignment position; liquidating.")
            self.equity_liquidation_ticket = self.Liquidate(self.spy)

    def _is_order_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in {
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted,
            OrderStatus.CancelPending
        }

    def OnOrderEvent(self, order_event: OrderEvent):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        order_type = str(order.Type)
        if "OptionExercise" in order_type:
            self.no_entry_today = True
            self.Debug("Unexpected option exercise or assignment detected.")
            if self.Portfolio[self.spy].Quantity != 0:
                self.equity_liquidation_ticket = self.Liquidate(self.spy)

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(
                    f"Option entry filled: {self.held_option.Value} "
                    f"at {self.entry_price:.4f}."
                )
            elif order_event.Status in {
                OrderStatus.Canceled,
                OrderStatus.Invalid
            }:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Option position liquidated: {self.held_option.Value}.")
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in {
                OrderStatus.Canceled,
                OrderStatus.Invalid
            }:
                self.exit_ticket = None

        if (
            self.equity_liquidation_ticket is not None and
            order_event.OrderId == self.equity_liquidation_ticket.OrderId and
            order_event.Status in {
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            }
        ):
            self.equity_liquidation_ticket = None

