from AlgorithmImports import *
from datetime import timedelta


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .Strikes(-1000, 1000)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.current_bucket_start = None
        self.current_bucket_bars = {}

        self.entry_ticket = None
        self.entry_pending = False
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None

        self.exit_ticket = None
        self.exit_pending = False
        self.no_entry_date = None
        self.spy_liquidation_ticket = None

    def OnData(self, slice: Slice):
        now = self.Time
        current_date = now.date()

        self.HandleUnexpectedEquityPosition()

        if self.held_symbol is not None:
            if self.expiration_date is not None and current_date >= self.expiration_date:
                self.no_entry_date = current_date
                self.SubmitExit("expiration")
            else:
                self.EvaluateProfitTarget(slice)
                self.EvaluateTimeStop()

        bar = None
        if slice.Bars.ContainsKey(self.spy):
            bar = slice.Bars[self.spy]

        if bar is not None:
            completed = self.AddMinuteBar(bar)
            if completed is not None:
                self.ProcessFiveMinuteBar(completed, slice)

    def AddMinuteBar(self, bar):
        start = bar.Time
        date = start.date()

        if start.time() < time(9, 30) or start.time() >= time(16, 0):
            return None

        bucket_minute = (start.minute // 5) * 5
        bucket_start = datetime(
            date.year, date.month, date.day,
            start.hour, bucket_minute
        )

        completed = None

        if self.current_bucket_start is None:
            self.current_bucket_start = bucket_start
        elif bucket_start != self.current_bucket_start:
            if len(self.current_bucket_bars) == 5:
                completed = self.BuildFiveMinuteBar()
            self.current_bucket_bars = {}
            self.current_bucket_start = bucket_start

        self.current_bucket_bars[start] = bar
        return completed

    def BuildFiveMinuteBar(self):
        bars = [
            self.current_bucket_bars[self.current_bucket_start + timedelta(minutes=i)]
            for i in range(5)
        ]

        return TradeBar(
            self.current_bucket_start,
            self.spy,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars),
            timedelta(minutes=5)
        )

    def ProcessFiveMinuteBar(self, bar, slice):
        close_time = bar.EndTime.time()

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        previous_fast = self.fast.Current.Value
        previous_slow = self.slow.Current.Value

        if not hasattr(self, "previous_fast"):
            self.previous_fast = previous_fast
            self.previous_slow = previous_slow
            return

        bullish_crossover = (
            self.previous_fast <= self.previous_slow
            and previous_fast > previous_slow
        )

        self.previous_fast = previous_fast
        self.previous_slow = previous_slow

        if not bullish_crossover:
            return

        if not (time(9, 45) <= close_time <= time(14, 30)):
            return

        if self.held_symbol is not None or self.entry_pending:
            return

        if self.no_entry_date == self.Time.date():
            return

        self.SelectAndEnterOption(slice)

    def SelectAndEnterOption(self, slice):
        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        today = self.Time.date()
        minimum_expiration = today + timedelta(days=7)

        contracts = []
        for chain in chains:
            contracts.extend(list(chain.Contracts.Values))

        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        selected_expiration = expirations[0]
        calls = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
        ]

        if not calls:
            self.Debug("Skipped entry: no call at selected expiration.")
            return

        underlying_price = self.Securities[self.spy].Price
        if underlying_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        selected = min(
            calls,
            key=lambda contract: (
                abs(float(contract.Strike) - float(underlying_price)),
                float(contract.Strike)
            )
