from collections import deque
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)

        self.previous_fast = None
        self.previous_slow = None

        self.minute_buckets = {}
        self.current_slice = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_block_date = None
        self.assignment_block_date = None

    def OnData(self, slice: Slice):
        self.current_slice = slice

        if self.Portfolio[self.spy_symbol].Quantity != 0:
            quantity = self.Portfolio[self.spy_symbol].Quantity
            self.Debug(
                f"Unexpected exercise or assignment handling at {self.Time}: "
                f"liquidating {quantity} SPY shares."
            )
            self.assignment_block_date = self.Time.date()

            if self._ticket_is_open(self.entry_ticket):
                self.entry_ticket.Cancel("Unexpected SPY equity position")

            self.MarketOrder(self.spy_symbol, -quantity)

        self._process_expiration()
        self._evaluate_option_exit()

        if self.spy_symbol in slice.Bars:
            self._update_five_minute_bar(slice.Bars[self.spy_symbol])

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        end_time = minute_bar.EndTime
        bar_time = end_time.time()

        if bar_time < time(9, 31) or bar_time > time(16, 0):
            return

        bucket_minute = ((end_time.minute - 1) // 5 + 1) * 5
        bucket_end = end_time.replace(
            minute=0, second=0, microsecond=0
        ) + timedelta(minutes=bucket_minute)

        bucket = self.minute_buckets.setdefault(
            bucket_end,
            {"bars": [], "last_close": None}
        )
        bucket["bars"].append(minute_bar)
        bucket["last_close"] = minute_bar.Close

        completed_keys = [
            key for key in self.minute_buckets
            if key <= bucket_end
        ]

        for key in sorted(completed_keys):
            data = self.minute_buckets.pop(key)

            if key != bucket_end or len(data["bars"]) != 5:
                continue

            self._on_five_minute_bar(key, data["last_close"])

    def _on_five_minute_bar(self, end_time, close):
        prior_fast = None
        prior_slow = None

        if len(self.fast_window) == 5:
            prior_fast = sum(self.fast_window) / 5.0
        if len(self.slow_window) == 20:
            prior_slow = sum(self.slow_window) / 20.0

        self.fast_window.append(close)
        self.slow_window.append(close)

        if len(self.fast_window) < 5 or len(self.slow_window) < 20:
            return

        current_fast = sum(self.fast_window) / 5.0
        current_slow = sum(self.slow_window) / 20.0

        crossover = (
            prior_fast is not None
            and prior_slow is not None
            and prior_fast <= prior_slow
            and current_fast > current_slow
        )

        if not crossover:
            return

        bar_time = end_time.time()
        if not (time(9, 45) <= bar_time <= time(14, 30)):
            return

        if self.expiration_block_date == self.Time.date():
            return

        if self.assignment_block_date == self.Time.date():
            return

        if self._ticket_is_open(self.entry_ticket):
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Quantity != 0:
            return

        self._try_enter_from_chain()

    def _try_enter_from_chain(self):
        chain = self.current_slice.OptionChains.get(self.option_symbol)

        if chain is None:
            self.Debug(f"Skipped option selection at {self.Time}: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug(
                f"Skipped option selection at {self.Time}: "
                f"no expiration at least seven calendar days away."
            )
            return

        selected_expiry = expiries[0]
        underlying_price = self.Securities[self.spy_symbol].Price

        calls = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike > 0
        ]

        if not calls:
            self.Debug(
                f"Skipped option selection at {self.Time}: "
                f"no call contract at expiration {selected_expiry}."
            )
            return

        selected = min(
            calls,
            key=lambda contract: (
                abs(float(contract.Strike) - underlying_price),
                float(contract.Strike)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            f"Entry submitted at {self.Time}: {selected.Symbol}, "
            f"expiration {selected_expiry}, strike {selected.Strike}."
        )

    def _evaluate_option_exit(self):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity <= 0 or self.entry_price is None:
            return

        quote = self.current_slice.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50% profit target")

    def _process_expiration(self):
        if self.held_symbol is None:
            return

        expiration_date = self.held_symbol.ID.Date.date()
        current_date = self.Time.date()
        current_time = self.Time.time()

        if current_date >= expiration_date:
            self.expiration_block_date = current_date
            self._submit_exit("expiration protection")
            return

        if (
            current_date == expiration_date - timedelta(days=1)
            and current_time >= time(15, 45)
        ):
            self._submit_exit("day-before-expiration time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug(
            f"Exit submitted at {self.Time}: {self.held_symbol}; reason: {reason}."
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            self.held_symbol = order_event.Symbol
            self.entry_price = order_event.FillPrice
            self.Debug(
                f"Entry filled at {self.Time}: {self.held_symbol}, "
                f"fill price {self.entry_price}."
            )

        elif (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            self.Debug(
                f"Exit filled at {self.Time}: {order_event.Symbol}, "
                f"fill price {order_event.FillPrice}."
            )
            self.held_symbol = None
            self.entry_price = None
            self.exit_ticket = None

    def _ticket_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

