from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyBullishCrossoverCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_canonical = option.Symbol

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.pending_signal_time = None
        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.no_entry_date = None
        self.equity_cleanup_ticket = None

    def _on_five_minute_bar(self, sender, bar):
        local_time = bar.EndTime

        if local_time.hour < 9 or local_time.hour > 16:
            return
        if local_time.hour == 9 and local_time.minute < 35:
            return
        if local_time.hour == 16 and local_time.minute > 0:
            return

        self.slow_closes.append(float(bar.Close))
        self.fast_closes.append(float(bar.Close))

        if len(self.slow_closes) < 20 or len(self.fast_closes) < 5:
            return

        current_fast = sum(self.fast_closes) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        if (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        ):
            bar_time = local_time.time()
            if (
                (bar_time.hour > 9 or (bar_time.hour == 9 and bar_time.minute >= 45))
                and (bar_time.hour < 14 or (bar_time.hour == 14 and bar_time.minute <= 30))
            ):
                self.pending_signal_time = local_time

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def OnData(self, slice):
        today = self.Time.date()

        if self.Portfolio[self.spy].Invested:
            self._liquidate_unexpected_equity()

        if self.entry_symbol is not None:
            self._manage_open_option(slice, today)

        if (
            self.pending_signal_time is not None
            and self.Time >= self.pending_signal_time
        ):
            signal_time = self.pending_signal_time
            self.pending_signal_time = None

            if self.Time == signal_time:
                self._evaluate_entry(slice, today)

    def _manage_open_option(self, slice, today):
        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested:
            return

        expiry = self.entry_symbol.ID.Date.date()

        if today >= expiry:
            self.no_entry_date = today
            self._submit_exit("expiration processing")
            return

        if self._is_trading_day_before_expiration(today, expiry):
            if self.Time.hour > 15 or (self.Time.hour == 15 and self.Time.minute >= 45):
                self.no_entry_date = today
                self._submit_exit("expiration time stop")
                return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            return

        contract = self._find_current_contract(slice, self.entry_symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50% profit target")

    def _evaluate_entry(self, slice, today):
        if self.no_entry_date == today:
            return

        if self.entry_ticket is not None and self._is_open(self.entry_ticket):
            return

