from datetime import datetime, date, time, timedelta

from QuantConnect import Resolution
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.DataNormalizationMode import DataNormalizationMode
from QuantConnect.Securities.Option import OptionRight
from QuantConnect.Orders import OrderStatus


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.spy_option.Symbol
        self.spy_option.SetFilter(-100, 100, 7, 365)

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.bucket_date = None
        self.bucket_start = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.no_entry_date = None
        self.assignment_liquidation_submitted = False

    def OnData(self, slice):
        self._handle_unexpected_equity_position()

        if self.held_symbol is not None and self.expiration_date is not None:
            if self.Time.date() >= self.expiration_date:
                self.no_entry_date = self.Time.date()
                if self._option_quantity() != 0:
                    self._submit_exit("expiration processing")
                return

            if (
                self.Time.date() == self.expiration_date - timedelta(days=1)
                and self.Time.time() >= time(15, 45)
                and self._option_quantity() != 0
            ):
                self._submit_exit("expiration time stop")

        if self.spy_symbol not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy_symbol]
        self._process_minute_bar(minute_bar, slice)

    def _process_minute_bar(self, minute_bar, slice):
        bar_time = minute_bar.Time
        local_date = bar_time.date()
        local_time = bar_time.time()

        if local_time < time(9, 30) or local_time >= time(16, 0):
            return

        minutes_from_open = (local_time.hour - 9) * 60 + local_time.minute - 30
        bucket_minute = 30 + (minutes_from_open // 5) * 5
        bucket_start = datetime(
            local_date.year,
            local_date.month,
            local_date.day,
            bucket_minute // 60,
            bucket_minute % 60
        )

        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.bucket_date = local_date
            self.bucket_bars = []

        self.bucket_bars.append(minute_bar)

        if len(self.bucket_bars) != 5:
            return

        expected_times = [
            bucket_start + timedelta(minutes=i) for i in range(5)
        ]
        actual_times = [bar.Time for bar in self.bucket_bars]

        if actual_times != expected_times:
            self.bucket_bars = []
            return

        consolidated_close = self.bucket_bars[-1].Close
        consolidated_end = bucket_start + timedelta(minutes=5)

        self.bucket_bars = []

        previous_fast = None
        previous_slow = None
        if len(self.closes) >= self.slow_period:
            previous_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            previous_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        self.closes.append(consolidated_close)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not bullish_cross:
            return

        end_time = consolidated_end.time()
        if end_time < time(9, 45) or end_time > time(14, 30):
            return

        self._evaluate_entry(slice, consolidated_end.date(), consolidated_close)

    def _evaluate_entry(self, slice, algorithm_date, underlying_price):
        if self.no_entry_date == algorithm_date:
            return

        if self.held_symbol is not None and self._option_quantity() != 0:
            return

        if self.entry_ticket is not None and self._entry_order_open():
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped call selection: no option chain in current Slice.")
            return

        minimum_expiration = algorithm_date + timedelta(days=7)

        contracts = list(chain.Contracts.Values)
        expirations = sorted(
            {
                contract.Expiry.date()
                for contract in contracts
                if contract.Expiry.date() >= minimum_expiration
            }
        )

        if not expirations:
            self.Debug("Skipped call selection: no expiration at least 7 days out.")
            return

        selected_expiration = expirations[0]

        calls = [
            contract
            for contract in contracts
            if (
                contract.Expiry.date() == selected_expiration
                and contract.Right == OptionRight.Call
            )
        ]

        if not calls:
            self.Debug("Skipped call selection: no call at selected expiration.")
            return

        selected_contract = min(
            calls,
            key=lambda contract: (
                abs(float(contract.Strike) - float(underlying_price)),
                float(contract.Strike)
            )
        )

        self.entry_ticket = self.MarketOrder(selected_contract.Symbol, 1)
        self.Debug(
            "Submitted SPY call entry: {} expiration {} strike {}".format(
                selected_contract.Symbol.Value,
                selected_expiration,
                selected_contract.Strike
            )
        )

    def _submit_exit(self, reason):
        quantity = self._option_quantity()
        if quantity == 0 or self.held_symbol is None:
            return

        if self.exit_ticket is not None:
            try:
                if self.exit_ticket.Status not in (
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket.Cancel("Replaced by {}".format(reason))
            except Exception:
                pass

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Submitted SPY call exit: {}".format(reason))

    def _option_quantity(self):
        if self.held_symbol is None:
            return 0
        return int(self.Portfolio[self.held_symbol].Quantity)

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False
        return self.entry_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _get_current_option_contract(self, slice):
        if self.held_symbol is None:
            return None

        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(self.held_symbol)
            if contract is not None:
                return contract

        return None

    def _check_profit_target(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self._option_quantity() == 0:
            return

        contract = self._get_current_option_contract(slice)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _handle_unexpected_equity_position(self):
        quantity = int(self.Portfolio[self.spy_symbol].Quantity)
        if quantity == 0:
            self.assignment_liquidation_submitted = False
            return

        if not self.assignment_liquidation_submitted:
            self.MarketOrder(self.spy_symbol, -quantity)
            self.assignment_liquidation_submitted = True
            self.no_entry_date = self.Time.date()
            self.Debug(
                "Unexpected SPY equity position detected; liquidated immediately."
            )

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.expiration_date = (
                    self.Securities[self.held_symbol].Symbol.ID.Date.date()
                )
                self.entry_ticket = None
                self.Debug(
                    "SPY call entry filled: {} at {}".format(
                        self.held_symbol.Value,
                        self.entry_price
                    )
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug("SPY call exit filled at {}".format(order_event.FillPrice))
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
                self.expiration_date = None

        if getattr(order_event, "IsAssignment", False):
            self.no_entry_date = self.Time.date()
            self._handle_unexpected_equity_position()
            self.Debug("Unexpected option exercise or assignment handled.")

    def OnAssignmentOrder(self, assignment_event):
        self.no_entry_date = self.Time.date()
        self._handle_unexpected_equity_position()
        self.Debug("Unexpected option assignment handled.")

    def OnEndOfAlgorithm(self):
        if self.held_symbol is not None and self._option_quantity() != 0:
            self._submit_exit("end of algorithm")

