        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()
        self._process_expiration()
        self._manage_option_position(slice)

        if not slice.Bars.ContainsKey(self.spy):
            return

        bar = slice.Bars[self.spy]
        self._update_five_minute_bar(bar, self.Time)

    def _update_five_minute_bar(self, bar: TradeBar, timestamp: datetime):
        local_time = timestamp.time()

        if local_time < time(9, 31) or local_time > time(16, 0):
            return

        minute = timestamp.hour * 60 + timestamp.minute
        bucket_end_minute = 575 + 5 * ((minute - 571) // 5)
        bucket_end = timestamp.replace(
            hour=bucket_end_minute // 60,
            minute=bucket_end_minute % 60,
            second=0,
            microsecond=0
        )

        if self.bucket_end != bucket_end:
            self._finalize_bucket()
            self.bucket_end = bucket_end
            self.bucket_bars = []
            self.bucket_valid = True

        if self.bucket_bars:
            expected_minute = self.bucket_bars[-1].EndTime + timedelta(minutes=1)
            if timestamp != expected_minute:
                self.bucket_valid = False

        self.bucket_bars.append(bar)

        if timestamp == bucket_end:
            self._finalize_bucket()

    def _finalize_bucket(self):
        if self.bucket_end is None or not self.bucket_bars:
            return

        expected_times = {
            self.bucket_end - timedelta(minutes=4),
            self.bucket_end - timedelta(minutes=3),
            self.bucket_end - timedelta(minutes=2),
            self.bucket_end - timedelta(minutes=1),
            self.bucket_end
        }

        actual_times = {bar.EndTime for bar in self.bucket_bars}

        if (
            self.bucket_valid
            and len(self.bucket_bars) == 5
            and actual_times == expected_times
        ):
            close = self.bucket_bars[-1].Close
            self._process_completed_five_minute_bar(close, self.bucket_end)

        self.bucket_end = None
        self.bucket_bars = []
        self.bucket_valid = True

    def _process_completed_five_minute_bar(self, close: float, bar_end: datetime):
        self.closes.append(float(close))

        if len(self.closes) < 21:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(list(self.closes)[-20:]) / 20.0

        previous_closes = list(self.closes)[:-1]
        previous_fast = sum(previous_closes[-5:]) / 5.0
        previous_slow = sum(previous_closes[-20:]) / 20.0

        bullish_crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        if bullish_crossover and eligible_time:
            self._try_enter_call(close)

    def _try_enter_call(self, underlying_price: float):
        current_date = self.Time.date()

        if self.no_entry_date == current_date:
            return

        if self.held_option is not None:
            return

        if self._entry_order_open() or self._exit_order_open():
            return

        if not self.CurrentSlice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no option chain")
            return

        chain = self.CurrentSlice.OptionChains[self.option_symbol]

        minimum_expiry = current_date + timedelta(days=7)
        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not candidates:
            self.Debug("Skipped entry: no eligible call expiration")
            return

        selected_expiry = min(contract.Expiry.date() for contract in candidates)

        expiry_contracts = [
            contract for contract in candidates
            if contract.Expiry.date() == selected_expiry
        ]

        if not expiry_contracts:
            self.Debug("Skipped entry: no eligible call contract")
            return

        selected = min(
            expiry_contracts,
            key=lambda contract: (
                abs(float(contract.Strike) - underlying_price),
                float(contract.Strike)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Call entry submitted: {0}, strike {1}, expiry {2}".format(
                selected.Symbol,
                selected.Strike,
                selected.Expiry.date()
            )
        )

    def _manage_option_position(self, slice: Slice):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        if self._exit_order_open():
            return

        if not slice.QuoteBars.ContainsKey(self.held_option):
            return

        quote = slice.QuoteBars[self.held_option]
        bid = quote.Bid.Close if quote.Bid is not None else 0
        ask = quote.Ask.Close if quote.Ask is not None else 0

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50% profit target")

    def _process_expiration(self):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.no_entry_date = current_date
            if self.Portfolio[self.held_option].Invested:
                self._submit_exit("expiration processing")
            return

        preceding_trading_day = self._previous_trading_day(expiry_date)

        if (
            current_date == preceding_trading_day
            and self.Time.time() >= time(15, 45)
            and self.Portfolio[self.held_option].Invested
        ):
            self._submit_exit("expiration time stop")

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        if self._exit_order_open():
            self.exit_ticket.Cancel("Replacing exit order")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug("Option exit submitted: " + reason)

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy]

        if holding.Quantity != 0:
            self.Debug("Unexpected SPY exercise or assignment; liquidating equity")
            self.MarketOrder(self.spy, -holding.Quantity)

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def _exit_order_open(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if (
                order_event.Status in (
                    OrderStatus.PartiallyFilled,
                    OrderStatus.Filled
                )
                and order_event.FillQuantity > 0
            ):
                self.held_option = self.entry_ticket.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Call entry filled: {0} at {1}".format(
                        self.held_option,
                        self.entry_price
                    )
                )

            if order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Option position exited")
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

