            .IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._previous_fast = None
        self._previous_slow = None
        self._pending_signal = False

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._blocked_entry_date = None
        self._spy_liquidation_ticket = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def _on_five_minute_bar(self, sender, bar):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if (
            previous_fast is not None
            and previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
        ):
            bar_time = bar.EndTime.time()
            if time(9, 45) <= bar_time <= time(14, 30):
                if (
                    previous_fast <= previous_slow
                    and self.fast.Current.Value > self.slow.Current.Value
                ):
                    self._pending_signal = True

        self._previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self._previous_slow = self.slow.Current.Value if self.slow.IsReady else None

    def OnData(self, slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_processing(slice)
        self._handle_time_stop()
        self._handle_profit_target(slice)

        if self._pending_signal:
            self._pending_signal = False
            self._try_entry(slice)

    def _try_entry(self, slice):
        today = self.Time.date()

        if self._blocked_entry_date == today:
            return

        if self._has_option_position() or self._entry_order_open():
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = today + timedelta(days=7)
        contracts = []

        for chain in chains:
            for contract in chain:
                if (
                    contract.Right == OptionRight.Call
                    and contract.Expiry.date() >= minimum_expiry
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no eligible call expiration.")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in contracts
        )
        expiry_contracts = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
        ]

        underlying_price = self.Securities[self.spy].Price
        if underlying_price <= 0:
            self.Debug("Skipped entry: unavailable SPY price.")
            return

        selected = min(
            expiry_contracts,
            key=lambda contract: (
                abs(float(contract.Strike) - underlying_price),
                float(contract.Strike)
            )
        )

        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} {} call.".format(
                selected.Symbol.Value,
                selected.Expiry.date()
            )
        )

    def _handle_profit_target(self, slice):
        if not self._has_option_position():
            return

        if self._exit_order_open():
            return

        quote = slice.QuoteBars.get(self._held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (float(bid) + float(ask)) / 2.0
        if self._entry_price is not None and midpoint >= 1.5 * self._entry_price:
            self._submit_exit("50% profit target")

    def _handle_time_stop(self):
        if not self._has_option_position() or self._exit_order_open():
            return

        security = self.Securities[self._held_symbol]
        expiry_date = security.Symbol.ID.Date.date()
        stop_date = self._previous_trading_day(expiry_date)

        if self.Time.date() == stop_date and self.Time.time() >= time(15, 45):
            self._submit_exit("pre-expiration time stop")

    def _handle_expiration_processing(self, slice):
        if not self._has_option_position():
            return

        expiry_date = self.Securities[self._held_symbol].Symbol.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self._blocked_entry_date = self.Time.date()
            if not self._exit_order_open():
                self._submit_exit("expiration protection")

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy]
        if not holding.Invested:
            return

        if (
            self._spy_liquidation_ticket is not None
            and self._is_open(self._spy_liquidation_ticket)
        ):
            return

        self.Debug("Unexpected SPY exercise or assignment position; liquidating.")
        self._spy_liquidation_ticket = self.MarketOrder(
            self.spy,
            -holding.Quantity
        )

    def _submit_exit(self, reason):
        if self._held_symbol is None:
            return

        if self._exit_order_open():
            self._exit_ticket.Cancel("Replacing exit order.")

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity != 0:
            self._exit_ticket = self.MarketOrder(
                self._held_symbol,
                -quantity
            )
            self.Debug(
                "Exit submitted: {}.".format(reason)
            )

    def OnOrderEvent(self, order_event):
        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option assignment or exercise received.")

        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_symbol = order_event.Symbol
                self._entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {} at {:.4f}.".format(
                        order_event.Symbol.Value,
                        self._entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Filled
            ):
                if order_event.Status != OrderStatus.Filled:
                    self._entry_ticket = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: {}.".format(order_event.Symbol.Value))
            self._exit_ticket = None
            self._entry_ticket = None
            self._held_symbol = None
            self._entry_price = None

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _has_option_position(self):
        return (
            self._held_symbol is not None
            and self.Portfolio[self._held_symbol].Invested
        )

    def _entry_order_open(self):
        return (
            self._entry_ticket is not None
            and self._is_open(self._entry_ticket)
        )

    def _exit_order_open(self):
        return (
            self._exit_ticket is not None
            and self._is_open(self._exit_ticket)
        )

    def _is_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

