from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyBullishCallStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False
        ).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(
            DataNormalizationMode.Raw
        )

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            -100,
            100,
            timedelta(days=0),
            timedelta(days=365)
        )
        self.option = option

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.fast_period = 5
        self.slow_period = 20

        self.pending_minutes = []
        self.pending_date = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_today = False
        self.last_algorithm_date = None

    def OnData(self, slice):
        current_date = self.Time.date()

        if self.last_algorithm_date != current_date:
            self.last_algorithm_date = current_date
            self.no_entry_today = False

        self._handle_unexpected_equity_position()
        self._process_expiration()
        self._process_option_exit()

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._accumulate_minute_bar(bar, slice)

    def _accumulate_minute_bar(self, bar, slice):
        end = bar.EndTime
        local_date = end.date()

        if self.pending_date != local_date:
            self.pending_minutes = []
            self.pending_date = local_date

        # Minute bars ending at minute 1 begin each five-minute interval.
        if not self.pending_minutes:
            if end.minute % 5 != 1:
                return
            self.pending_minutes = [bar]
            return

        previous_end = self.pending_minutes[-1].EndTime
        if end - previous_end != timedelta(minutes=1):
            self.pending_minutes = []
            if end.minute % 5 == 1:
                self.pending_minutes = [bar]
            return

        self.pending_minutes.append(bar)

        if end.minute % 5 == 0:
            bars = self.pending_minutes
            self.pending_minutes = []

            if len(bars) != 5:
                return

            close = bars[-1].Close
            self._process_five_minute_close(end, close, slice)

    def _process_five_minute_close(self, end, close, slice):
        previous_fast_ready = len(self.fast_values) >= self.fast_period
        previous_slow_ready = len(self.slow_values) >= self.slow_period

        previous_fast = (
            sum(self.fast_values) / self.fast_period
            if previous_fast_ready else None
        )
        previous_slow = (
            sum(self.slow_values) / self.slow_period
            if previous_slow_ready else None
        )

        self.fast_values.append(float(close))
        self.slow_values.append(float(close))

        current_fast_ready = len(self.fast_values) >= self.fast_period
        current_slow_ready = len(self.slow_values) >= self.slow_period

        if not (
            previous_fast_ready
            and previous_slow_ready
            and current_fast_ready
            and current_slow_ready
        ):
            return

        current_fast = sum(self.fast_values) / self.fast_period
        current_slow = sum(self.slow_values) / self.slow_period

        bullish_crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not bullish_crossover or self.no_entry_today:
            return

        if not (end.hour > 9 or (end.hour == 9 and end.minute >= 45)):
            return
        if not (end.hour < 14 or (end.hour == 14 and end.minute <= 30)):
            return

        if self.held_symbol is not None:
            return
        if self._order_is_open(self.entry_ticket):
            return

        self._try_enter(slice, close)

    def _try_enter(self, slice, underlying_price):
        chain = None

        for candidate in slice.OptionChains.Values:
            if candidate.Symbol == self.option.Symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped entry: no current SPY option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain.Contracts.Values
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        selected_expiry = expirations[0]

        calls = [
            contract
            for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike > 0
        ]

        if not calls:
            self.Debug("Skipped entry: no eligible call at selected expiration.")
            return

        if underlying_price is None or underlying_price <= 0:
            self.Debug("Skipped entry: invalid underlying price.")
            return

        # Select the call whose strike is closest to the current SPY price.
        selected = min(
            calls,
            key=lambda contract: (
                abs(float(contract.Strike) - float(underlying_price)),
                float(contract.Strike)
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _process_option_exit(self):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self._order_is_open(self.exit_ticket):
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity <= 0:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.no_entry_today = True
            self._submit_exit("Expiration liquidation")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)
        if (
            self.Time.date() == previous_trading_day
            and (self.Time.hour > 15 or
                 (self.Time.hour == 15 and self.Time.minute >= 45))
        ):
            self._submit_exit("Pre-expiration time stop")
            return

        quote = self.Securities[self.held_symbol]
        if not quote.HasData:
            return

        bid = float(quote.BidPrice)
        ask = float(quote.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity <= 0:
            return

        if self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order")
            self.exit_ticket = None

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -holding.Quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {0}, quantity {1}".format(
                reason,
                holding.Quantity
            )
        )

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.Debug(
                        "Entered {0} call at {1}".format(
                            self.held_symbol,
                            self.entry_price
                        )
                    )
                    self.entry_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.Debug("Entry order did not fill.")
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exited {0} at {1}".format(
                            order_event.Symbol,
                            order_event.FillPrice
                        )
                    )
                    self.exit_ticket = None
                    self.held_symbol = None
                    self.entry_price = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

    def _process_expiration(self):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.no_entry_today = True
            if not self._order_is_open(self.exit_ticket):
                self._submit_exit("Expiration processing liquidation")

    def _handle_unexpected_equity_position(self):
        if self.Portfolio[self.spy].Quantity == 0:
            return

        self.no_entry_today = True
        self.Debug(
            "Unexpected SPY equity position detected; liquidating immediately."
        )
        self.Liquidate(self.spy, tag="Unexpected exercise or assignment")

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(
            DateTime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _order_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted
        )

