from datetime import datetime, timedelta


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 730)
        )
        self.option = option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self._bucket_end = None
        self._bucket_bars = {}

        self._held_symbol = None
        self._entry_price = None
        self._entry_order = None
        self._exit_order = None
        self._spy_cleanup_order = None
        self._no_entry_date = None

    def OnData(self, slice: Slice):
        self._liquidate_unexpected_spy_position()

        if self._held_symbol is not None:
            self._process_option_exit(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        current_date = end_time.date()

        if not (end_time.hour == 9 and end_time.minute >= 31 or
                10 <= end_time.hour < 16):
            return

        if end_time.hour == 9 and end_time.minute > 35:
            pass
        elif end_time.hour == 9 and end_time.minute < 31:
            return

        minutes_after_open = (end_time.hour * 60 + end_time.minute) - (9 * 60 + 30)
        bucket_minute = 9 * 60 + 30 + ((minutes_after_open - 1) // 5 + 1) * 5
        bucket_end = datetime(
            current_date.year,
            current_date.month,
            current_date.day,
            bucket_minute // 60,
            bucket_minute % 60
        )

        if self._bucket_end is not None and bucket_end != self._bucket_end:
            self._finalize_bucket(self._bucket_end, slice)

        if self._bucket_end is None or bucket_end != self._bucket_end:
            self._bucket_end = bucket_end
            self._bucket_bars = {}

        self._bucket_bars[end_time] = bar

    def _finalize_bucket(self, bucket_end: datetime, slice: Slice):
        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if not all(t in self._bucket_bars for t in expected_times):
            self._bucket_bars = {}
            return

        five_minute_close = self._bucket_bars[expected_times[-1]].Close
        self._bucket_bars = {}

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.slow_period:
            previous_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            previous_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        self.closes.append(float(five_minute_close))
        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        eligible_time = (
            bucket_end.hour > 9 or
            (bucket_end.hour == 9 and bucket_end.minute >= 45)
        ) and (
            bucket_end.hour < 14 or
            (bucket_end.hour == 14 and bucket_end.minute <= 30)
        )

        if (
            previous_fast is not None and
            previous_slow is not None and
            previous_fast <= previous_slow and
            current_fast > current_slow and
            eligible_time
        ):
            self._try_enter(slice, bucket_end.date())

    def _try_enter(self, slice: Slice, signal_date):
        if self._no_entry_date == signal_date:
            return

        if self._entry_order is not None and not self._entry_order.Status.IsClosed():
            return

        if self._held_symbol is not None:
            return

        chains = list(slice.OptionChains)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = signal_date + timedelta(days=7)
        selected_expiry = None
        selected_chain = None

        for chain in chains:
            contracts = list(chain.Contracts.Values)
            for contract in contracts:
                expiry_date = contract.Expiry.date()
                if expiry_date < minimum_expiry:
                    continue
                if selected_expiry is None or expiry_date < selected_expiry:
                    selected_expiry = expiry_date
                    selected_chain = chain

        if selected_chain is None:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        underlying_price = float(self.Securities[self.spy].Price)
        if underlying_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        calls = [
            contract for contract in selected_chain.Contracts.Values
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
        ]

        if not calls:
            self.Debug("Skipped entry: no call at selected expiration.")
            return

        calls.sort(key=lambda c: (abs(float(c.Strike) - underlying_price), float(c.Strike)))
        selected_contract = calls[0]

        self._entry_order = self.MarketOrder(
            selected_contract.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _process_option_exit(self, slice: Slice):
        if self._held_symbol is None:
            return

        holding = self.Portfolio[self._held_symbol]
        quantity = holding.Quantity

        if quantity <= 0:
            self._held_symbol = None
            self._entry_price = None
            return

        now = self.Time
        expiry_date = self._held_symbol.ID.Date.date()

        if now.date() >= expiry_date:
            self._no_entry_date = now.date()
            self._submit_option_exit(quantity, "Expiration protection")
            return

        if (
            now.time() >= datetime(2000, 1, 1, 15, 45).time()
            and self._is_immediately_preceding_trading_day(now.date(), expiry_date)
        ):
            self._submit_option_exit(quantity, "Pre-expiration time stop")
            return

        if self._entry_price is None:
            return

        bid, ask = self._get_current_bid_ask(slice, self._held_symbol)
        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self._entry_price:
            self._submit_option_exit(quantity, "50 percent profit target")

    def _get_current_bid_ask(self, slice: Slice, symbol):
        quote_bar = slice.QuoteBars.get(symbol)
        if quote_bar is not None:
            bid = quote_bar.Bid.Close if quote_bar.Bid is not None else None
            ask = quote_bar.Ask.Close if quote_bar.Ask is not None else None
            return (
                float(bid) if bid is not None else None,
                float(ask) if ask is not None else None
            )

        for chain in slice.OptionChains:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                bid = contract.BidPrice
                ask = contract.AskPrice
                return (
                    float(bid) if bid is not None else None,
                    float(ask) if ask is not None else None
                )

        return None, None

    def _submit_option_exit(self, quantity, tag):
        if self._exit_order is not None and not self._exit_order.Status.IsClosed():
            return

        self._exit_order = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag=tag
        )

    def _is_immediately_preceding_trading_day(self, current_date, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return current_date == candidate

    def _liquidate_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if self._spy_cleanup_order is None or self._spy_cleanup_order.Status.IsClosed():
            self.Debug("Unexpected SPY exercise or assignment; liquidating equity.")
            self._spy_cleanup_order = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment cleanup"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self._entry_order is not None and order_event.OrderId == self._entry_order.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self._held_symbol = order_event.Symbol
                self._entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entered 1 SPY call at {:.2f}.".format(self._entry_price)
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self._entry_order = None
            return

        if self._exit_order is not None and order_event.OrderId == self._exit_order.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exited SPY call: {}.".format(self._exit_order.Tag))
                self._held_symbol = None
                self._entry_price = None
                self._exit_order = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self._exit_order = None
            return

        if (
            self._spy_cleanup_order is not None
            and order_event.OrderId == self._spy_cleanup_order.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Unexpected SPY equity position liquidated.")

