        except Exception:
            try:
                return slice.Bars[self.spy]
            except Exception:
                pass
        return None

    def _update_five_minute_bar(self, minute_bar, slice: Slice):
        bar_time = minute_bar.Time
        bar_date = bar_time.date()
        bar_clock = bar_time.time()

        if not (time(9, 30) <= bar_clock < time(16, 0)):
            return

        minute_index = (bar_time.hour * 60 + bar_time.minute) - (9 * 60 + 30)
        if minute_index < 0:
            return

        bucket_index = minute_index // 5
        expected_start = datetime.combine(
            bar_date, time(9, 30)
        ) + timedelta(minutes=bucket_index * 5)

        if self.bucket_start != expected_start:
            self.bucket_start = expected_start
            self.current_bucket_date = bar_date
            self.bucket_bars = []

        if bar_time != self.bucket_start + timedelta(minutes=len(self.bucket_bars)):
            self.bucket_bars = []
            self.bucket_start = expected_start
            return

        self.bucket_bars.append(minute_bar)

        if len(self.bucket_bars) != 5:
            return

        completed_end = self.bucket_start + timedelta(minutes=5)
        closes = [x.Close for x in self.bucket_bars]

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(completed_end, closes[-1])
        self.slow.Update(completed_end, closes[-1])

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self.previous_fast = self.fast.Current.Value
        self.previous_slow = self.slow.Current.Value
        self.bucket_bars = []

        end_clock = completed_end.time()
        eligible = time(9, 45) <= end_clock <= time(14, 30)

        if bullish_cross and eligible:
            self._evaluate_entry(slice, closes[-1], completed_end.date())

    def _evaluate_entry(self, slice: Slice, spot_price: float, signal_date):
        if signal_date == self.no_entry_date:
