            return

        contract = self._get_current_contract(slice, self.held_option)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        if self.entry_price is not None:
            midpoint = (bid + ask) / 2.0
            if midpoint >= 1.5 * self.entry_price:
                self._liquidate_option("50 percent profit target")

    def _get_current_contract(self, slice: Slice, symbol):
        try:
            for chain in slice.OptionChains.Values:
                if chain.Contracts.ContainsKey(symbol):
                    return chain.Contracts[symbol]
        except Exception:
            pass
        return None

    def _liquidate_option(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self._cancel_open_exit_orders()
        self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
        self.Debug("Call exit submitted: {0}.".format(reason))

    def _cancel_open_exit_orders(self):
        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

    def _ticket_is_open(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if (
            self.entry_ticket is not None
            and orderEvent.OrderId == self.entry_ticket.OrderId
        ):
            if orderEvent.Status in (OrderStatus.Filled, OrderStatus.PartiallyFilled):
                if orderEvent.FillQuantity > 0:
                    self.held_option = self.entry_ticket.Symbol
                    self.entry_price = float(orderEvent.FillPrice)
                    self.Debug(
                        "Call entry filled: {0} at {1}.".format(
                            self.held_option.Value, self.entry_price
                        )
                    )
            elif orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and orderEvent.OrderId == self.exit_ticket.OrderId
            and orderEvent.Status == OrderStatus.Filled
        ):
            self.Debug("Call position exited at {0}.".format(orderEvent.FillPrice))
            self.held_option = None
            self.entry_price = None
            self.expiration_date = None
            self.exit_ticket = None
            self.entry_ticket = None

    def OnAssignmentOrderEvent(self, assignmentEvent):
        self.no_entry_date = self.Time.date()
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.MarketOrder(self.spy, -quantity)
            self.Debug("Unexpected option assignment: liquidated SPY equity position.")
        else:
            self.Debug("Unexpected option exercise or assignment received.")

