from datetime import datetime, timedelta, time
from collections import deque


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(lambda u: u.IncludeWeeklys()
                         .Strikes(-100, 100)
                         .Expiration(0, 365))

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        self.HandleUnexpectedEquityPosition()

        if self.held_symbol is not None:
            self.EvaluateExit(slice)

        if self.entry_ticket is not None and not self.IsTerminal(self.entry_ticket.Status):
            return

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        self.ProcessMinuteBar(bar, slice)

    def ProcessMinuteBar(self, bar: TradeBar, slice: Slice):
        bar_start = bar.EndTime - timedelta(minutes=1)
        bucket_start = bar_start.replace(
            minute=(bar_start.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bucket_start != self.bucket_start:
            self.bucket_start = bucket_start
            self.bucket_bars = []

        self.bucket_bars.append(bar)

        expected_last_minute = self.bucket_start + timedelta(minutes=4)
        if bar_start != expected_last_minute or len(self.bucket_bars) != 5:
            return

        close = float(bar.Close)
        self.closes.append(close)
        self.bucket_bars = []

        if len(self.closes) < self.slow_period:
            return

        fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes) / self.slow_period

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end = self.bucket_start + timedelta(minutes=5)
        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        if bullish_cross and eligible_time:
            self.TryEnter(slice)

    def TryEnter(self, slice: Slice):
        current_date = self.Time.date()

        if self.no_entry_date == current_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self.IsTerminal(self.entry_ticket.Status):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        min_expiry = current_date + timedelta(days=7)
        contracts = list(chain.Contracts.Values)

        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= min_expiry
        })

        if not expiries:
            self.Debug("Skipped call selection: no qualifying expiration.")
            return

        selected_expiry = expiries[0]
        calls = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
        ]

        if not calls:
            self.Debug("Skipped call selection: no qualifying call contract.")
            return

        underlying_price = float(self.Securities[self.spy].Price)
        selected = min(
            calls,
            key=lambda contract: (
                abs(float(contract.Strike) - underlying_price),
                float(contract.Strike)
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def EvaluateExit(self, slice: Slice):
        symbol = self.held_symbol
        if symbol is None:
            return

        expiry_date = self.Securities[symbol].Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.SubmitExit("Expiration protection")
            self.no_entry_date = current_date
            return

        previous_trading_day = self.PreviousTradingDay(expiry_date)
        if (
            current_date == previous_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("Pre-expiration time stop")
            return

        quote = slice.QuoteBars.get(symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        if self.entry_price is not None:
            midpoint = (float(bid) + float(ask)) / 2.0
            if midpoint >= 1.5 * self.entry_price:
                self.SubmitExit("50 percent profit target")

    def SubmitExit(self, tag: str):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and not self.IsTerminal(self.exit_ticket.Status):
            self.exit_ticket.Cancel("Replaced by newer exit condition")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=tag
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment detected.")
            self.HandleUnexpectedEquityPosition()

        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.Debug(
                        "Entered 1 call: {} at {:.2f}".format(
                            self.held_symbol.Value,
                            self.entry_price
                        )
                    )
                    self.entry_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.Debug("Call entry order did not fill.")
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exited call: {} at {:.2f}".format(
                            order_event.Symbol.Value,
                            float(order_event.FillPrice)
                        )
                    )
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

    def HandleUnexpectedEquityPosition(self):
        holding = self.Portfolio[self.spy]
        if holding.Quantity != 0:
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.MarketOrder(
                self.spy,
                -holding.Quantity,
                tag="Unexpected exercise or assignment handling"
            )
            self.no_entry_date = self.Time.date()

    def PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, time.min)
        ):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def IsTerminal(status):
        return status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

