from AlgorithmImports import *
from collections import deque
from datetime import timedelta, time


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute, Market.USA, True, False)
        self.spy = equity.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        self.option.SetFilter(
            lambda universe: universe
            .Strikes(-100, 100)
            .Expiration(timedelta(0), timedelta(days=730))
        )

        self.fast_period = 5
        self.slow_period = 20
        self.fast_values = deque(maxlen=self.fast_period)
        self.slow_values = deque(maxlen=self.slow_period)

        self.bucket_start = None
        self.bucket_count = 0
        self.bucket_close = None
        self.bucket_seen = set()

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None

        self.no_entry_today = False
        self.current_day = None
        self.equity_cleanup_ticket = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.current_day != current_date:
            self.current_day = current_date
            self.no_entry_today = False

        self._handle_unexpected_equity_position()
        self._handle_expiration_processing()
        self._evaluate_minute_exit(slice)
        self._process_spy_minute_bar(slice)

    def _process_spy_minute_bar(self, slice: Slice):
        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        local_time = bar.Time

        if local_time.date() != self.Time.date():
            return

        if local_time.time() < time(9, 30) or local_time.time() >= time(16, 0):
            return

        minutes_from_open = int((local_time - datetime.combine(local_time.date(), time(9, 30))).total_seconds() // 60)
        bucket_start = datetime.combine(
            local_time.date(),
            time(9, 30)
        ) + timedelta(minutes=(minutes_from_open // 5) * 5)

        if self.bucket_start is None:
            self._start_bucket(bucket_start)
        elif bucket_start != self.bucket_start:
            self._finalize_bucket()
            self._start_bucket(bucket_start)

        if local_time not in self.bucket_seen:
            self.bucket_seen.add(local_time)
            self.bucket_count += 1
            self.bucket_close = bar.Close

    def _start_bucket(self, bucket_start):
        self.bucket_start = bucket_start
        self.bucket_count = 0
        self.bucket_close = None
        self.bucket_seen = set()

    def _finalize_bucket(self):
        if self.bucket_start is None:
            return

        if self.bucket_count != 5 or self.bucket_close is None:
            return

        fast_before = self._average(self.fast_values)
        slow_before = self._average(self.slow_values)

        self.fast_values.append(self.bucket_close)
        self.slow_values.append(self.bucket_close)

        fast_after = self._average(self.fast_values)
        slow_after = self._average(self.slow_values)

        if (
            fast_before is None
            or slow_before is None
            or fast_after is None
            or slow_after is None
        ):
            return

        bar_end = self.bucket_start + timedelta(minutes=5)
        eligible = time(9, 45) <= bar_end.time() <= time(14, 30)

        bullish_crossover = (
            fast_before <= slow_before
            and fast_after > slow_after
        )

        if (
            eligible
            and bullish_crossover
            and self.held_symbol is None
            and not self._entry_order_is_open()
            and not self.no_entry_today
        ):
            self._try_enter_from_current_slice()

    def _average(self, values):
        if not values:
            return None
        return sum(values) / len(values)

    def _try_enter_from_current_slice(self):
        # The current Slice is supplied through the consolidating data event.
        # LEAN exposes the most recent Slice through the algorithm's current data
        # only during OnData, so entry selection is performed from the cached chain.
        chain = self._current_option_chain

        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible_contracts = [
            contract for contract in chain
            if contract.Expiry.date() >= minimum_expiry
            and contract.Right == OptionRight.Call
        ]

        if not eligible_contracts:
            self.Debug("Skipped entry: no eligible call expiration.")
            return

        nearest_expiry = min(
            contract.Expiry.date() for contract in eligible_contracts
        )

        expiry_contracts = [
            contract for contract in eligible_contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        underlying_price = self.Securities[self.spy].Price
        if underlying_price <= 0 or not expiry_contracts:
            self.Debug("Skipped entry: no contract satisfies strike rules.")
            return

        selected = min(
            expiry_contracts,
            key=lambda contract: (
                abs(float(contract.Strike) - underlying_price),
                float(contract.Strike)
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish 5-minute MA crossover"
        )

    @property
    def _current_option_chain(self):
        return getattr(self, "__current_option_chain", None)

    @_current_option_chain.setter
    def _current_option_chain(self, value):
        self.__current_option_chain = value

    def OnDataConsolidated(self, sender, bar):
        pass

    def _evaluate_minute_exit(self, slice: Slice):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self._exit_order_is_open():
            return

        if (
            self.expiration_date is not None
            and self.Time.date() == self.expiration_date - timedelta(days=1)
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("Expiration time stop")
            return

        if self.held_symbol not in slice.BidAsks:
            return

        quote = slice.BidAsks[self.held_symbol]
        bid = quote.Bid
        ask = quote.Ask

        if bid <= 0 or ask <= 0 or self.entry_price is None:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._cancel_open_exit()
            self._submit_exit("50% profit target")

    def _handle_expiration_processing(self):
        if (
            self.held_symbol is not None
            and self.expiration_date is not None
            and self.Time.date() >= self.expiration_date
        ):
            self.no_entry_today = True
            if not self._exit_order_is_open():
                self._submit_exit("Expiration protection")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason}")

    def _cancel_open_exit(self):
        if self._exit_order_is_open():
            self.exit_ticket.Cancel("Replaced by profit-target exit")

    def _entry_order_is_open(self):
        return self._ticket_is_open(self.entry_ticket)

    def _exit_order_is_open(self):
        return self._ticket_is_open(self.exit_ticket)

    def _ticket_is_open(self, ticket):
        if ticket is None:
            return False
        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if not self._ticket_is_open(self.equity_cleanup_ticket):
            self.Debug("Unexpected exercise or assignment: liquidating SPY.")
            self.equity_cleanup_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment cleanup"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order.Symbol
                self.entry_price = order_event.FillPrice
                self.expiration_date = order.Symbol.ID.Date.date()
                self.Debug(
                    f"Entry filled: {order.Symbol} at {self.entry_price}"
                )
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order canceled or invalid.")
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order.Symbol}")
                if self.Portfolio[order.Symbol].Quantity == 0:
                    self.held_symbol = None
                    self.entry_price = None
                    self.expiration_date = None
                self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        order_type_text = str(order.Type)
        if "Exercise" in order_type_text or "Assignment" in order_type_text:
            self.no_entry_today = True
            self.Debug("Unexpected exercise or assignment processing detected.")
            self._handle_unexpected_equity_position()

