from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._bucket_start = None
        self._bucket_minutes = set()
        self._bucket_close = None

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._no_entry_today = False

    def OnData(self, slice: Slice):
        self._handle_expiration_and_assignment()
        self._evaluate_exit(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        local_time = bar.Time
        current_date = local_time.date()
        minute = local_time.hour * 60 + local_time.minute

        if minute < 570 or minute >= 960:
            return

        bucket_minute = minute - ((minute - 570) % 5)
        bucket_start = datetime(
            current_date.year,
            current_date.month,
            current_date.day,
            bucket_minute // 60,
            bucket_minute % 60
        )

        if self._bucket_start is not None and bucket_start != self._bucket_start:
            self._finish_bucket(slice)

        if self._bucket_start is None:
            self._bucket_start = bucket_start
            self._bucket_minutes = set()

        if local_time.minute not in range(bucket_minute, bucket_minute + 5):
            return

        if local_time not in self._bucket_minutes:
            self._bucket_minutes.add(local_time)
            self._bucket_close = bar.Close

    def _finish_bucket(self, slice: Slice):
        if self._bucket_start is None:
            return

        bucket_start = self._bucket_start
        bucket_end = bucket_start + timedelta(minutes=5)

        if len(self._bucket_minutes) == 5 and self._bucket_close is not None:
            self._on_completed_five_minute_bar(
                bucket_end,
                self._bucket_close,
                slice
            )

        self._bucket_start = None
        self._bucket_minutes = set()
        self._bucket_close = None

    def _on_completed_five_minute_bar(
        self,
        bar_end: datetime,
        close: float,
        slice: Slice
    ):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar_end, close)
        self.slow.Update(bar_end, close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if previous_fast is None or previous_slow is None:
            return

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)
        bullish_cross = (
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        if (
            eligible_time and
            bullish_cross and
            not self._no_entry_today and
            self._held_symbol is None and
            not self._has_open_entry_order()
        ):
            self._try_enter(slice, close)

    def _try_enter(self, slice: Slice, underlying_price: float):
        chain = slice.OptionChains.get(self.option_symbol)

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = [
            contract for contract in chain
            if contract.Expiration.date() >= minimum_expiry
        ]

        if not contracts:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = min(
            contract.Expiration.date() for contract in contracts
        )

        calls = [
            contract for contract in contracts
            if contract.Expiration.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike > 0
        ]

        if not calls:
            self.Debug("Skipped entry: no eligible call at selected expiration.")
            return

        selected = min(
            calls,
            key=lambda contract: (
                abs(contract.Strike - underlying_price),
                contract.Strike
            )
        )

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _evaluate_exit(self, slice: Slice):
        if self._held_symbol is None or self._entry_price is None:
            return

        holding = self.Portfolio[self._held_symbol]
        if not holding.Invested:
            return

        expiry = self._held_symbol.ID.Date.date()
        current_date = self.Time.date()

        if (
            current_date == self._previous_trading_day(expiry) and
            self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("Expiration-eve time stop")
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (c for c in chain if c.Symbol == self._held_symbol),
            None
        )

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self._entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason: str):
        if self._held_symbol is None:
            return

        if self._exit_ticket is not None and self._is_open(self._exit_ticket):
            self._exit_ticket.Cancel("Replacing exit order")

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity != 0:
            self._exit_ticket = self.MarketOrder(
                self._held_symbol,
                -quantity,
                tag=reason
            )
            self.Debug(
                "Exit submitted: {} {}".format(
                    self._held_symbol.Value,
                    reason
                )
            )

    def _handle_expiration_and_assignment(self):
        spy_holding = self.Portfolio[self.spy]
        if spy_holding.Quantity != 0:
            self.Debug("Unexpected SPY exercise or assignment; liquidating equity.")
            self.MarketOrder(
                self.spy,
                -spy_holding.Quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

        if self._held_symbol is not None:
            expiry = self._held_symbol.ID.Date.date()
            if self.Time.date() >= expiry:
                self._no_entry_today = True
                self.Debug("Unexpected option position at expiration; liquidating.")
                self._submit_exit("Expiration liquidation")

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_ticket is not None and
            order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_symbol = order_event.Symbol
                self._entry_price = order_event.FillPrice
                self._entry_ticket = None
                self.Debug(
                    "Entered {} call at filled price {:.4f}".format(
                        order_event.Symbol.Value,
                        self._entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order canceled or invalid.")
                self._entry_ticket = None

        if (
            self._exit_ticket is not None and
            order_event.OrderId == self._exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exited option position.")
                self._exit_ticket = None
                self._held_symbol = None
                self._entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._exit_ticket = None

        message = (order_event.Message or "").lower()
        if "exercise" in message or "assignment" in message:
            self.Debug("Unexpected exercise or assignment event received.")

    def _has_open_entry_order(self) -> bool:
        return (
            self._entry_ticket is not None and
            self._is_open(self._entry_ticket)
        )

    @staticmethod
    def _is_open(ticket) -> bool:
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _previous_trading_day(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = date_value - timedelta(days=1)

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate.date() if hasattr(candidate, "date") else candidate

