        current_date = bar_time.date()
        current_time = bar_time.time()

        if current_time < time(9, 30) or current_time >= time(16, 0):
            return None

        if self.bucket_date != current_date:
            self.minute_bucket = []
            self.bucket_date = current_date
            self.bucket_start = None

        if self.bucket_start is None:
            if current_time.minute % 5 != 0 or current_time.second != 0:
                return None
            self.bucket_start = bar_time
            self.minute_bucket = [minute_bar]
        else:
            expected_time = self.bucket_start + timedelta(minutes=len(self.minute_bucket))

            if bar_time != expected_time:
                self.minute_bucket = []
                self.bucket_start = None

                if current_time.minute % 5 != 0 or current_time.second != 0:
                    return None

                self.bucket_start = bar_time
                self.minute_bucket = [minute_bar]
            else:
                self.minute_bucket.append(minute_bar)

        if len(self.minute_bucket) != 5:
            return None

        bars = self.minute_bucket
        start = bars[0].Time
        end = bars[-1].EndTime

        consolidated = TradeBar(
            start,
            self.spy.Symbol,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars),
            timedelta(minutes=5)
        )

        self.minute_bucket = []
        self.bucket_start = None

        return consolidated

    def _evaluate_entry(self, slice, bar, current_date):
        bar_end = bar.EndTime
        end_time = bar_end.time()

        if not (time(9, 45) <= end_time <= time(14, 30)):
            return

        if self.no_entry_date == current_date:
