            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self._order_is_open(self.exit_ticket):
            if reason == "50% profit target":
                self.exit_ticket.Cancel("Replacing exit with profit-target liquidation.")
            else:
                return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug("Submitted SPY call exit: {}".format(reason))

    def _handle_expiration_processing(self, current_date):
        if self.held_option is None:
            return

        expiry_date = self.Securities[self.held_option].Symbol.ID.Date.date()
        if current_date >= expiry_date:
            self.no_entry_date = current_date
            if self.Portfolio[self.held_option].Invested:
                self._submit_exit("expiration processing")

    def _handle_unexpected_spy_position(self, current_date):
        if self.Portfolio[self.spy.Symbol].Quantity != 0:
            self.no_entry_date = current_date
            self.Debug("Unexpected SPY exercise or assignment; liquidating SPY.")
            self.MarketOrder(
                self.spy.Symbol,
                -self.Portfolio[self.spy.Symbol].Quantity,
                tag="Unexpected exercise or assignment handling"
            )

    def _get_option_chain(self, slice):
        try:
            chain = slice.OptionChains.get(self.option_symbol)
            if chain is not None:
                return chain
        except Exception:
            pass

        try:
            for key in slice.OptionChains.Keys:
                if key == self.option_symbol:
                    return slice.OptionChains[key]
        except Exception:
            pass

        try:
            for chain in slice.OptionChains.Values:
                if chain.Symbol == self.option_symbol:
                    return chain
        except Exception:
            pass

        return None

    def _get_held_contract(self, slice):
        chain = self._get_option_chain(slice)
        if chain is None:
            return None

        for contract in chain:
            if contract.Symbol == self.held_option:
                return contract

        return None

    def _order_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "SPY call entry filled: {} at {:.4f}".format(
                        order_event.Symbol,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self.Debug("SPY call entry did not fill.")
                self.entry_ticket = None
                self.held_option = None
                self.entry_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "SPY call exit filled: {} at {:.4f}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        if (
            order_event.Symbol == self.spy.Symbol
            and order_event.Status == OrderStatus.Filled
            and order_event.Direction in (OrderDirection.Buy, OrderDirection.Sell)
        ):
            self.Debug("Unexpected SPY exercise or assignment order event.")

