        self.entry_price = None
        self.exit_ticket = None

        self.pending_signal_end = None
        self.blocked_entry_date = None
        self.unexpected_equity_ticket = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        if bar.Symbol != self.spy.Symbol:
            return

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if previous_fast is None or previous_slow is None:
            return
        if not self.fast.IsReady or not self.slow.IsReady:
            return

        bar_time = bar.EndTime.time()
        if not (bar_time >= time(9, 45) and bar_time <= time(14, 30)):
            return

        if previous_fast <= previous_slow and self.fast.Current.Value > self.slow.Current.Value:
            self.pending_signal_end = bar.EndTime

    def OnData(self, slice):
        self.HandleUnexpectedEquityPosition()

        if self.held_symbol is not None:
            self.HandleExpirationProcessing()
            self.HandleOpenPositionExit(slice)

        if self.pending_signal_end is not None:
            signal_end = self.pending_signal_end
            self.pending_signal_end = None

            if self.Time >= signal_end:
                self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self.IsOpen(self.entry_ticket):
            return

        chain = self.GetOptionChain(slice)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = expirations[0]
        underlying_price = self.Securities[self.spy.Symbol].Price

        calls = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike > 0
        ]

        if not calls or underlying_price <= 0:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected_contract = min(
            calls,
            key=lambda contract: (abs(contract.Strike - underlying_price), contract.Strike)
        )

        self.entry_symbol = selected_contract.Symbol
        self.entry_ticket = self.MarketOrder(
            self.entry_symbol,
            1,
            tag="Bullish SPY crossover entry"
        )

    def HandleOpenPositionExit(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity <= 0:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry:
            self.blocked_entry_date = current_date
            self.SubmitExit("Expiration protection")
            return

        if current_date == expiry - timedelta(days=1) and self.Time.time() >= time(15, 45):
            self.SubmitExit("Expiration time stop")
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            return

        quote = self.GetCurrentQuote(slice, self.held_symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("50 percent profit target")

    def HandleExpirationProcessing(self):
        if self.held_symbol is None:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if self.Time.date() >= expiry:
            self.blocked_entry_date = self.Time.date()
            self.SubmitExit("Expiration protection")

