        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            self.Transactions.CancelOrder(
                self.exit_ticket.OrderId,
                "Replacing exit order"
            )

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def HandleUnexpectedEquityPosition(self):
        holding = self.Portfolio[self.spy.Symbol]
        if holding.Quantity == 0:
            return

        if self.unexpected_equity_ticket is not None and self.IsOpen(
            self.unexpected_equity_ticket
        ):
            return

        self.Debug("Unexpected SPY exercise or assignment position; liquidating.")
        self.unexpected_equity_ticket = self.MarketOrder(
            self.spy.Symbol,
            -holding.Quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def OnOrderEvent(self, order_event):
        if order_event.Status in (OrderStatus.Filled, OrderStatus.PartiallyFilled):
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Call entry filled: {0} at {1}".format(
                        order_event.Symbol.Value,
                        order_event.FillPrice
                    )
                )

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Option position exited.")
                self.held_symbol = None
                self.entry_price = None
                self.entry_symbol = None
                self.exit_ticket = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_ticket = None

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid)
        ):
            self.entry_ticket = None
            self.entry_symbol = None

        if getattr(order_event, "IsAssignment", False) or getattr(
            order_event, "IsExercise", False
        ):
            self.Debug("Unexpected option exercise or assignment detected.")
            self.HandleUnexpectedEquityPosition()

    def OnAssignmentOrder(self, assignment_event):
        self.Debug("Unexpected option assignment detected.")
        self.HandleUnexpectedEquityPosition()

    def GetOptionChain(self, slice):
        try:
            chain = slice.OptionChains.get(self.spy_option.Symbol)
            if chain is not None:
                return chain
        except Exception:
            pass

        for candidate in slice.OptionChains:
            if candidate.Key == self.spy_option.Symbol:
                return candidate.Value

        return None

    def GetCurrentQuote(self, slice, symbol):
        try:
            quote_bar = slice.QuoteBars.get(symbol)
            if quote_bar is not None:
                bid = quote_bar.Bid.Close
                ask = quote_bar.Ask.Close
                if bid is not None and ask is not None:
                    return float(bid), float(ask)
        except Exception:
            pass

        try:
            chain = self.GetOptionChain(slice)
            if chain is not None:
                for contract in chain:
                    if contract.Symbol == symbol:
                        return float(contract.BidPrice), float(contract.AskPrice)
        except Exception:
            pass

        return None

    def IsOpen(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

