from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 730)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)

        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket = None
        self.bucket_closes = []
        self.bucket_last_time = None
        self.bucket_valid = True

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None

        self.no_entry_date = None
        self.assignment_ticket = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self._handle_unexpected_spy_position(today)
        self._handle_expiration(today)

        if self.held_symbol is not None:
            self._evaluate_exit(slice, today)

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice, today)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice, today):
        local_time = self.Time.time()

        if local_time < time(9, 30) or local_time > time(16, 0):
            return

        minute = local_time.hour * 60 + local_time.minute
        bucket_end_minute = ((minute + 4) // 5) * 5
        bucket_end = (
            today,
            bucket_end_minute
        )

        if self.current_bucket is None:
            self._start_bucket(bucket_end, bar)
            return

        if bucket_end != self.current_bucket:
            self._complete_bucket(slice, today)
            self._start_bucket(bucket_end, bar)
            return

        if self.bucket_last_time is not None:
            expected = self.bucket_last_time + timedelta(minutes=1)
            if self.Time.replace(second=0, microsecond=0) != expected:
                self.bucket_valid = False

        self.bucket_closes.append(float(bar.Close))
        self.bucket_last_time = self.Time.replace(second=0, microsecond=0)

    def _start_bucket(self, bucket, bar):
        self.current_bucket = bucket
        self.bucket_closes = [float(bar.Close)]
        self.bucket_last_time = self.Time.replace(second=0, microsecond=0)
        self.bucket_valid = True

    def _complete_bucket(self, slice: Slice, today):
        if self.current_bucket is None:
            return

        bucket_end_minute = self.current_bucket[1]
        if not self.bucket_valid or len(self.bucket_closes) != 5:
            return

        close = self.bucket_closes[-1]
        self.closes.append(close)

        if len(self.closes) < self.slow_period:
            return

        fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes) / self.slow_period

        crossover = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        end_time = time(bucket_end_minute // 60, bucket_end_minute % 60)

        if (
            crossover and
            time(9, 45) <= end_time <= time(14, 30)
        ):
            self._evaluate_entry(slice, today, close)

    def _evaluate_entry(self, slice: Slice, today, underlying_price):
        if self.no_entry_date == today:
            return

        if self._has_option_holding() or self._entry_order_open():
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = today + timedelta(days=7)
        contracts = []

        for chain in chains:
            for contract in chain:
                expiry = contract.Expiry.date()
                if (
                    expiry >= minimum_expiry and
                    contract.Right == OptionRight.Call
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no eligible call expiration or contract.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in contracts)
        eligible = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
        ]

        if not eligible:
            self.Debug("Skipped entry: no eligible contract at selected expiration.")
            return

        selected = min(
            eligible,
            key=lambda contract: (
                abs(float(contract.Strike) - underlying_price),
                float(contract.Strike)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} call strike {:.2f}, expiry {}.".format(
                selected.Symbol,
                float(selected.Strike),
                selected_expiry
            )
        )

    def _evaluate_exit(self, slice: Slice, today):
        if self.held_symbol is None:
            return

        if self._exit_order_open():
            return

        expiry = self.expiration_date
        previous_trading_day = self._previous_trading_day(expiry)

        if (
            today == previous_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("time stop")
            return

        quote = slice.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (float(bid) + float(ask)) / 2.0

        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._exit_order_open():
            return

        if self.exit_ticket is not None and self._ticket_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Exit submitted: {}.".format(reason))

    def _handle_expiration(self, today):
        if self.held_symbol is None or self.expiration_date is None:
            return

        if today >= self.expiration_date:
            self.no_entry_date = today
            self._submit_exit("expiration protection")

    def _handle_unexpected_spy_position(self, today):
        holding = self.Portfolio[self.spy.Symbol]

        if holding.Invested:
            self.no_entry_date = today

            if (
                self.assignment_ticket is None or
                not self._ticket_open(self.assignment_ticket)
            ):
                self.assignment_ticket = self.MarketOrder(
                    self.spy.Symbol,
                    -holding.Quantity
                )
                self.Debug(
                    "Unexpected exercise or assignment: liquidating SPY equity."
                )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_ticket.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.expiration_date = (
                    self.Securities[self.held_symbol]
                    .Symbol
                    .ID
                    .Date
                    .date()
                )
                self.Debug(
                    "Entry filled: {} at {:.4f}.".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Filled
            ):
                if order_event.Status != OrderStatus.Filled:
                    self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {} at {:.4f}.".format(
                        self.held_symbol,
                        float(order_event.FillPrice)
                    )
                )
                self.held_symbol = None
                self.entry_price = None
                self.expiration_date = None
                self.exit_ticket = None

    def _has_option_holding(self):
        for security in self.Securities.Values:
            if (
                security.Type == SecurityType.Option and
                self.Portfolio[security.Symbol].Invested
            ):
                return True
        return False

